window.WORKBOOK={"title": "Around the World in 80 Integrals", "course": "Math 23B · Application Worksheets", "version": 1, "accessed": "2026-11-17", "sources": {"noaa": {"title": "NOAA Monterey Harbor tidal datums", "url": "https://tidesandcurrents.noaa.gov/benchmarks/9413450.html", "kind": "Published observation-derived datums", "note": "Station 9413450; epoch 1983–2001; benchmark sheet published October 12, 2011. Meters above MLLW. These are long-term reference levels, not successive tide readings or a forecast.", "headers": ["Datum", "Height above MLLW (m)"], "rows": [["MHHW", "1.626"], ["MHW", "1.412"], ["MTL", "0.873"], ["MSL", "0.862"], ["MLW", "0.333"], ["MLLW", "0.000"]]}, "river": {"title": "USGS San Lorenzo River at Santa Cruz", "url": "https://pubs.usgs.gov/wdr/WDR-CA-00-2/pdf/WRD.CA.00.Vol2.pdf", "kind": "Historical measurements", "note": "Station 11161000; Water Resources Data—California, water year 2000, Volume 2, printed page 101. Daily mean discharge; not instantaneous velocity. March 1–4, 2000.", "headers": ["Date", "Daily mean discharge (ft³/s)"], "rows": [["2000-03-01", "755"], ["2000-03-02", "614"], ["2000-03-03", "539"], ["2000-03-04", "475"]]}, "reserve": {"title": "UCSC Younger Lagoon Reserve", "url": "https://youngerlagoonreserve.ucsc.edu/about-us/", "kind": "Published site areas", "note": "Reserve website reports the areas below. An equal-area ellipse, rectangle, or polygon in a problem is a teaching model, not a surveyed reserve boundary.", "headers": ["Component", "Area (acres)"], "rows": [["Original lagoon reserve", "25"], ["Terrace Lands", "47"], ["Total reserve", "72"]]}, "aquarium": {"title": "Monterey Bay Aquarium facts and figures", "url": "https://www.montereybayaquarium.org/about-us/about-the-aquarium/newsroom/media-kits/facts-and-figures", "kind": "Published dimensions and capacities", "note": "Published exhibit dimensions and capacities, accessed November 17, 2026. They are not a survey of tank shape or a measured spatial velocity field.", "headers": ["Exhibit", "Published dimensions / capacity"], "rows": [["Open Sea", "90 ft across; 52 ft front to back; 35 ft tall; 1,200,000 US gal"], ["Kelp Forest", "28 ft tall; 343,000 US gal"], ["Sea Otters", "15 ft tall; 55,000 US gal"]]}, "pump": {"title": "Monterey Bay Aquarium Kelp Forest", "url": "https://www.montereybayaquarium.org/visit/exhibits/kelp-forest/", "kind": "Published upper operating rate", "note": "The exhibit page describes pumps pushing up to 2,000 US gallons per minute. Use this as a stated upper rate, not as a measurement at a particular moment. Any pipe radius or velocity profile below is assumed.", "headers": ["Quantity", "Published value"], "rows": [["Pump flow", "Up to 2,000 US gal/min"], ["Exhibit height", "28 ft"]]}, "rover": {"title": "MBARI Benthic Rover II", "url": "https://www.mbari.org/news/autonomous-robotic-rover-helps-scientists-with-long-term-monitoring-of-deep-sea-carbon-cycle-and-climate-change/", "kind": "Published equipment dimensions", "note": "MBARI article, November 2021. These are overall dimensions. Boxes, panels, housings, and paths used here are hypothetical models, not the rover’s actual shape or route.", "headers": ["Dimension", "Reported value (m)"], "rows": [["Length", "2.6"], ["Width", "1.7"], ["Height", "1.5"]]}, "mars": {"title": "MBARI Monterey Accelerated Research System", "url": "https://www.mbari.org/technology/monterey-accelerated-research-system-mars/", "kind": "Published observatory depth", "note": "MBARI reports its MARS node at 891 m depth. A straight path or force field in this workbook is hypothetical; it is not a reconstruction of the actual cable.", "headers": ["Quantity", "Reported value"], "rows": [["Node depth", "891 m"]]}, "earth": {"title": "NASA Earth Fact Sheet", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html", "kind": "Published planetary parameters", "note": "NASA NSSDC Earth Fact Sheet, accessed November 17, 2026. The volumetric mean radius is the radius of a sphere with Earth’s volume; the real Earth is slightly flattened at the poles.", "headers": ["Quantity", "Published value"], "rows": [["Volumetric mean radius", "6371.000 km"], ["Obliquity to orbit (axial tilt)", "23.44°"]]}, "alma": {"title": "ALMA Memo 574: 12 m antenna optics", "url": "https://science.nrao.edu/facilities/alma/aboutALMA/Technology/ALMA_Memo_Series/alma574/memo574.pdf", "kind": "Published antenna design parameters", "note": "Sugimoto et al. (NAOJ ALMA project office), ALMA Memo 574, 2007, Table 1. The memo states that the ACA 12 m antenna shares the optics parameters of the 12 m antennas used for ALMA. The tabulated values are for the 12 m prototype design.", "headers": ["Quantity", "Published value"], "rows": [["Primary mirror diameter", "12 m"], ["Primary focal length", "4800 mm"], ["Primary focal ratio f/D", "0.4"], ["Vertex hole diameter", "750 mm"]]}, "cooling": {"title": "Niederaussem natural-draft cooling tower", "url": "https://structurae.net/en/literature/journal-article/world-s-tallest-natural-draft-cooling-tower", "kind": "Published structural dimensions", "note": "Busch, Harte, Krätzig and Montag, Structural Engineering International 11(2), 2001, describe the 200 m tower. The 152 m base diameter and 0.24 m wall thickness come from co-author W. B. Krätzig’s summary on shellbuckling.com. The narrowest radius and exact shape in the problem are assumed.", "headers": ["Quantity", "Published value"], "rows": [["Height", "200 m"], ["Base diameter", "152 m"], ["Shell wall thickness", "about 0.24 m"]]}, "zimbabwe": {"title": "Great Zimbabwe: the Conical Tower", "url": "https://en.wikipedia.org/wiki/Great_Zimbabwe", "kind": "Published approximate dimensions (secondary source)", "note": "Wikipedia’s Great Zimbabwe article, citing P. Garlake, Great Zimbabwe (1973), p. 29, gives the dimensions below. Other descriptions differ by about a metre. The top radius used in the problem is assumed.", "headers": ["Quantity", "Reported value"], "rows": [["Height", "30 ft (about 9 m)"], ["Base diameter", "18 ft (about 5.5 m)"]]}, "iter": {"title": "ITER EDA Newsletter (IAEA), October 2000", "url": "https://www-pub.iaea.org/MTCD/Publications/PDF/Newsletters/ITER-NL-9-10.pdf", "kind": "Published design parameters", "note": "International Atomic Energy Agency, ITER EDA Newsletter Vol. 9 No. 10, lists the plasma parameters below. The real plasma cross-section is D-shaped, not circular.", "headers": ["Quantity", "Published value"], "rows": [["Plasma major radius", "6.2 m"], ["Plasma minor radius", "2.0 m"], ["Plasma volume", "837 m³"]]}}, "weeks": [{"week": 2, "title": "Tides, habitats, and double integrals", "subtitle": "A Tale of Two Orders", "skills": ["Build Riemann sums with area factors", "Use symmetry, comparison, and piecewise integrands", "Describe a region in both orders", "Evaluate iterated integrals", "Reverse order to make integration possible"], "formulas": ["$\\iint_D f\\,dA\\approx\\sum f(x_i^*,y_i^*)\\,\\Delta A_i$", "$V=\\iint_D(\\text{top}-\\text{bottom})\\,dA$"], "sources": ["noaa", "reserve", "aquarium"], "problems": [{"title": "A tide-scaled water-depth map", "context": "NOAA reports MLW at $0.333$ m above MLLW in Monterey Harbor. Set $H=0.333$ m and consider a hypothetical $100$ m by $50$ m basin with depth $h(x,y)=H(1+x/100+y/50)$.", "model": "Only H is source-derived. The basin, its bed, and the depth field are assumed; datum elevation is not generally water depth.", "sources": ["noaa"], "work": "Draw a $2\\times2$ grid. List the upper-right and midpoint sample locations, calculate each height, and include the common patch area.", "questions": [{"prompt": "What is the area of each grid cell?", "expected": "1250", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["The whole rectangle has area 5,000 square meters.", "There are four equal cells."], "id": "w02-p1-a", "label": "a"}, {"prompt": "Find the upper-right Riemann-sum volume.", "expected": "4162.5", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Use x=50,100 and y=25,50.", "The four heights sum to 3.33 m."], "id": "w02-p1-b", "label": "b"}, {"prompt": "Find the midpoint estimate and verify it by an exact iterated integral.", "expected": "3330", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Midpoints have x=25,75 and y=12.5,37.5.", "The mean of this affine depth field is 2H."], "id": "w02-p1-c", "label": "c"}], "solution": ["Cell widths are $50$ m and $25$ m, so $\\Delta A=1250$ m$^2$.", "Upper-right depths are $2H,2.5H,2.5H,3H$. Their sum is $10H$, giving $1250(10)(0.333)=4162.5$ m$^3$.", "Midpoint depths are $1.5H,2H,2H,2.5H$, giving $1250(8H)=3330$ m$^3$.", "Exactly, $\\int_0^{100}\\int_0^{50}H(1+x/100+y/50)\\,dy\\,dx=5000(2H)=3330$ m$^3$."], "reflection": "Explain why the upper-right sum overestimates. Would a midpoint sum always be exact for a nonlinear depth field?", "extension": false, "diagram": "grid", "discussionSolution": "The depth increases with both coordinates, so each upper-right sample is the cell maximum. Midpoint exactness here comes from an affine function; it generally fails for nonlinear depths.", "id": "w02-p1"}, {"title": "Restoration bands with jumps", "context": "The Younger Lagoon Reserve includes restoration habitat. In an invented $100$ m square plot use $x=50u$, $y=50v$, $0\\le u,v\\le2$. Planting-material density is $\\delta=\\lfloor u+v\\rfloor$ kg/m$^2$.", "model": "The reserve is real; this plot and planting-density rule are hypothetical. Boundaries of the bands have zero area.", "sources": ["reserve"], "work": "Sketch $u+v=1,2,3$ and shade the four constant-density bands. Explain the integrability criterion.", "questions": [{"prompt": "Find the physical area on which the density is 1.", "expected": "3750", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Its normalized area is 2 minus 1/2.", "The coordinate scaling multiplies area by 2,500."], "id": "w02-p2-a", "label": "a"}, {"prompt": "Find the total mass of planting material.", "expected": "15000", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["The normalized band areas are 1/2,3/2,3/2,1/2.", "Multiply each band area by its density, then multiply the sum by 2,500."], "id": "w02-p2-b", "label": "b"}, {"prompt": "Why does the density have a Riemann integral?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Check boundedness and the size of the discontinuity set.", "The jump lines and the corner (2,2) have zero area."], "options": ["Every discontinuous function is integrable.", "It is bounded and its discontinuities form a zero-area set.", "Its discontinuities have positive area."], "id": "w02-p2-c", "label": "c"}], "solution": ["$dA=2500\\,du\\,dv$. The density-1 band has physical area $2500(3/2)=3750$ m$^2$.", "The weighted normalized area is $0(1/2)+1(3/2)+2(3/2)+3(1/2)=6$. Thus mass is $2500(6)=15000$ kg.", "The value at $(u,v)=(2,2)$ is 4; that corner is also a relative discontinuity. Boundedness and a zero-area discontinuity set ensure integrability."], "reflection": "Why does changing the density on the jump lines leave the total mass unchanged?", "extension": false, "discussionSolution": "Line segments and finitely many points have zero area. For a bounded integrand, changing values only there leaves the integral unchanged.", "id": "w02-p2"}, {"title": "A triangular monitoring plot", "context": "Use an invented coastal plot $D=\\{0\\le x\\le100,\\ 0\\le y\\le x/2\\}$, with sediment loading $c(x,y)=1+x/100$ g/m$^2$. The scale is chosen for a field exercise near Younger Lagoon.", "model": "The location is contextual. The triangle and sediment-loading function are teaching assumptions.", "sources": ["reserve"], "work": "Sketch D, describe vertical and horizontal slices, and write both orders for the mass integral.", "questions": [{"prompt": "Find the plot area.", "expected": "2500", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["It is a triangle with base 100 and height 50.", "Area is half base times height."], "id": "w02-p3-a", "label": "a"}, {"prompt": "Find its sediment mass.", "expected": "12500/3", "units": "g", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate (1+x/100) over y from 0 to x/2.", "The remaining integrand is x/2+x^2/200."], "id": "w02-p3-b", "label": "b"}, {"prompt": "For order $dx\\,dy$, enter the outer lower, outer upper, inner lower, inner upper bounds as four comma-separated expressions.", "expected": ["0", "50", "2*y", "100"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Solve y ≤ x/2 for x.", "At fixed y, the slice starts at x=2y and ends at 100."], "id": "w02-p3-c", "label": "c"}], "solution": ["The vertices are $(0,0),(100,0),(100,50)$, so area is $2500$ m$^2$.", "$M=\\int_0^{100}\\int_0^{x/2}(1+x/100)\\,dy\\,dx=\\int_0^{100}(x/2+x^2/200)\\,dx=12500/3$ g.", "The reversed description is $0\\le y\\le50$, $2y\\le x\\le100$. Thus $M=\\int_0^{50}\\int_{2y}^{100}(1+x/100)\\,dx\\,dy$."], "reflection": "Which boundary becomes the left edge of a horizontal slice?", "extension": false, "diagram": "triangle", "discussionSolution": "The line y=x/2 becomes x=2y, the left boundary of a horizontal slice. The right boundary is x=100.", "id": "w02-p3"}, {"title": "A spatial index across an exhibit footprint", "context": "The Aquarium publishes Open Sea dimensions of $90$ ft across and $52$ ft front to back. Treat the footprint as a rectangle and set $u=x/90$, $v=y/52$. An invented dimensionless illumination index is $f(u,v)=u e^{uv}$.", "model": "Dimensions are published; the rectangular footprint and illumination index are models, not lighting measurements.", "sources": ["aquarium"], "work": "Express the physical area element in u,v coordinates and compare which integration order is easier. Use symmetry to integrate x−45 over the footprint, and bound the illumination index before calculating.", "questions": [{"prompt": "Find the physical footprint area.", "expected": "4680", "units": "ft²", "kind": "number", "tolerance": 1e-05, "hints": ["Multiply 90 by 52.", "The same number is the constant coordinate area factor."], "id": "w02-p4-a", "label": "a"}, {"prompt": "Find $\\int_0^1 u e^{uv}\\,dv$ as a function of u.", "expected": "exp(u)-1", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Treat u as constant.", "Differentiate e^(uv) with respect to v."], "id": "w02-p4-b", "label": "b"}, {"prompt": "Find the integral of the index over the physical footprint.", "expected": "4680*(e-2)", "units": "index·ft²", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate e^u-1 from 0 to 1.", "Multiply the normalized integral by 4,680."], "id": "w02-p4-c", "label": "c"}], "solution": ["The model footprint has area $90(52)=4680$ ft$^2$ and $dA=4680\\,du\\,dv$.", "For fixed $u$, $\\int_0^1u e^{uv}\\,dv=[e^{uv}]_0^1=e^u-1$, including $u=0$.", "The normalized integral is $[e^u-u]_0^1=e-2$. The physical integral is $4680(e-2)$ index-ft$^2$."], "reflection": "Why are the units of this index integral different from an average index?", "extension": false, "discussionSolution": "The integral has units index times area; an average divides by area and has only index units. On a rectangle centered at x=45, the integral of x−45 is zero by odd symmetry. Since 0≤u≤1 and 1≤exp(uv)≤e, the index lies between 0 and e, so its physical integral lies between 0 and 4680e.", "id": "w02-p4"}, {"title": "Reverse a sensor-footprint integral", "context": "For an invented $100$ m scale coastal survey, use $x=100u$, $y=100v$ on $0\\le u\\le v\\le1$. A dimensionless sensitivity index is $e^{v^2}$.", "model": "This is an analytical sensor model inspired by coastal monitoring; it is not a calibrated instrument response.", "sources": ["noaa"], "work": "Explain why integrating v first has no elementary antiderivative, then reverse the order.", "questions": [{"prompt": "Find the physical survey area.", "expected": "5000", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["The normalized region is half a unit square.", "Multiply by 100²."], "id": "w02-p5-a", "label": "a"}, {"prompt": "Find the integral of the sensitivity index over the physical area.", "expected": "5000*(e-1)", "units": "index·m²", "kind": "number", "tolerance": 1e-05, "hints": ["At fixed v, u runs from 0 to v.", "Use w=v^2 after integrating u."], "id": "w02-p5-b", "label": "b"}, {"prompt": "Find the area-average sensitivity index.", "expected": "e-1", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Divide the total index integral by area.", "The physical coordinate factor cancels."], "id": "w02-p5-c", "label": "c"}], "solution": ["The triangular region has area $10000/2=5000$ m$^2$.", "Reversing gives $10000\\int_0^1\\int_0^v e^{v^2}\\,du\\,dv=10000\\int_0^1v e^{v^2}\\,dv$.", "With $w=v^2$, this is $5000[e^w]_0^1=5000(e-1)$. Dividing by $5000$ gives mean $e-1$."], "reflection": "Explain why a larger survey area does not automatically imply a larger average sensitivity.", "extension": true, "discussionSolution": "An integral adds contributions from every patch; an average divides by the total area. Expanding the region can raise or lower an average depending on the newly included values.", "id": "w02-p5"}]}, {"week": 3, "title": "Water volumes and three-dimensional sampling", "subtitle": "Life Is Like a Box of Integrals", "skills": ["Reverse order and split a region", "Project solids onto coordinate planes", "Build triple-integral bounds", "Separate box integrals", "Interpret historical discharge correctly"], "formulas": ["$V=\\iiint_E1\\,dV$", "$M=\\iiint_E\\delta\\,dV$", "$1\\ \\mathrm{ft}^3=0.028316846592\\ \\mathrm{m}^3$"], "sources": ["noaa", "rover", "river"], "problems": [{"title": "A tide-difference wedge", "context": "NOAA gives MHW $1.412$ m and MLW $0.333$ m. Let $H=1.079$ m be their difference. In a hypothetical $100$ m by $50$ m basin, water occupies $0\\le z\\le H(1-x/100)$.", "model": "This is a difference of long-term datums, not a particular day’s tidal range. The basin geometry and floor are invented.", "sources": ["noaa"], "work": "Draw the xy shadow and build a $dz\\,dy\\,dx$ triple integral. Here z is height above the modeled floor.", "questions": [{"prompt": "Enter the upper z bound as a function of x.", "expected": "1.079*(1-x/100)", "units": "m", "kind": "expression", "tolerance": 1e-05, "hints": ["The top is H when x=0 and zero when x=100.", "Use the stated linear top."], "id": "w03-p1-a", "label": "a"}, {"prompt": "Find water volume.", "expected": "100*50*1.079/2", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate height over the rectangular shadow.", "The average height is H/2."], "id": "w03-p1-b", "label": "b"}, {"prompt": "Find the height moment $\\iiint_E z\\,dV$.", "expected": "100*50*1.079^2/6", "units": "m⁴", "kind": "number", "tolerance": 1e-05, "hints": ["The inner integral of z is top²/2.", "Integrate (1-x/100)^2 over x."], "id": "w03-p1-c", "label": "c"}], "solution": ["$V=\\int_0^{100}\\int_0^{50}\\int_0^{H(1-x/100)}1\\,dz\\,dy\\,dx$. The shadow is the full rectangle.", "$V=50H\\int_0^{100}(1-x/100)\\,dx=2500H=2697.5$ m$^3$.", "The moment is $50(H^2/2)\\int_0^{100}(1-x/100)^2\\,dx=5000H^2/6$ m$^4$. Its units have one additional factor of length."], "reflection": "Use the moment-to-volume ratio to predict whether the average height is H/2 or H/3.", "extension": false, "discussionSolution": "The moment-to-volume ratio is H/3, not H/2. The wedge contains more volume near its bottom than near its top.", "id": "w03-p1"}, {"title": "A region that must be split", "context": "A hypothetical sampling footprint is described in local coordinates $x=10u$, $y=10v$ meters by $v^2\\le u\\le v+2$.", "model": "This is a constructed coastal sampling boundary, not a mapped real shoreline.", "sources": ["noaa"], "work": "Find intersections. Set up area in both orders and identify where vertical slices change bottom boundary.", "questions": [{"prompt": "Enter intersection coordinates in normalized coordinates as u1,v1,u2,v2, in increasing v order.", "expected": ["1", "-1", "4", "2"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Solve v²=v+2.", "The roots are -1 and 2."], "id": "w03-p2-a", "label": "a"}, {"prompt": "Find physical area.", "expected": "450", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Normalized area is the integral of v+2-v² from -1 to 2.", "Scale area by 100."], "id": "w03-p2-b", "label": "b"}, {"prompt": "At what physical x coordinate must the reversed area integral split?", "expected": "10", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["The lower boundaries meet at normalized u=1.", "x=10u."], "id": "w03-p2-c", "label": "c"}], "solution": ["$v^2=v+2$ gives $v=-1,2$ and points $(u,v)=(1,-1),(4,2)$.", "$A=100\\int_{-1}^2\\int_{v^2}^{v+2}1\\,du\\,dv=100(9/2)=450$ m$^2$.", "For $0\\le u\\le1$, $-\\sqrt u\\le v\\le\\sqrt u$; for $1\\le u\\le4$, $u-2\\le v\\le\\sqrt u$. Thus split at $x=10$ m."], "reflection": "Why is there only one integral in one order but two in the other?", "extension": false, "diagram": "split", "discussionSolution": "Horizontal slices have one left and one right boundary throughout. Vertical slices change their lower boundary from −sqrt(u) to u−2 at u=1.", "id": "w03-p2"}, {"title": "A rover-sized test chamber", "context": "MBARI reports Benthic Rover II dimensions $2.6$ m by $1.7$ m by $1.5$ m. Model a rectangular calibration chamber with those dimensions and density $\\delta(x,y,z)=1+z$ kg/m$^3$, where z is the numerical height in meters.", "model": "The dimensions are real; the chamber and its density are fictional. The coefficient of z carries the units needed to make density consistent.", "sources": ["rover"], "work": "Write the box bounds and a triple integral for mass. Then insert an additional z for the height moment.", "questions": [{"prompt": "Find chamber volume.", "expected": "6.63", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Multiply the three dimensions.", "2.6×1.7 is the base area."], "id": "w03-p3-a", "label": "a"}, {"prompt": "Find mass.", "expected": "11.6025", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate 1+z from 0 to 1.5.", "Multiply by base area 4.42."], "id": "w03-p3-b", "label": "b"}, {"prompt": "Find the center-of-mass height.", "expected": "6/7", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Use ∫z(1+z)dV divided by mass.", "The height moment is 9.945 kg·m."], "id": "w03-p3-c", "label": "c"}], "solution": ["$V=2.6(1.7)(1.5)=6.63$ m$^3$.", "$M=\\int_0^{2.6}\\int_0^{1.7}\\int_0^{1.5}(1+z)\\,dz\\,dy\\,dx=4.42[z+z^2/2]_0^{1.5}=11.6025$ kg.", "$N_z=4.42[z^2/2+z^3/3]_0^{1.5}=9.945$ kg-m. Thus $\\bar z=N_z/M=6/7$ m, higher than the uniform midpoint $0.75$ m."], "reflection": "Why can the x and y integrals be factored out, but the z moment still needs integration?", "extension": false, "discussionSolution": "The x and y bounds are constant and the density depends only on z, so those integrations supply the constant base area. A height moment weights each mass element by its z coordinate.", "id": "w03-p3"}, {"title": "A nested sampling solid", "context": "In a hypothetical three-dimensional coastal survey, $x=10u$, $y=10v$, $z=10w$ meters with $0\\le w\\le v\\le u\\le1$. Concentration is modeled as $e^{u^3}$ kg/m$^3$.", "model": "The solid and concentration are analytical teaching models.", "sources": ["rover"], "work": "Explain why the given du-first order is awkward. Rewrite with u outermost and integrate w then v.", "questions": [{"prompt": "Find physical volume.", "expected": "1000/6", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["The normalized ordered simplex is 1/6 of the unit cube.", "Each physical coordinate has scale 10."], "id": "w03-p4-a", "label": "a"}, {"prompt": "Find total modeled mass.", "expected": "1000*(e-1)/6", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["For fixed u the vw triangle has area u²/2.", "Substitute a=u³ after the inner two integrations."], "id": "w03-p4-b", "label": "b"}, {"prompt": "Enter bounds for order $dw\\,dv\\,du$, outer bounds first: umin,umax,vmin,vmax,wmin,wmax.", "expected": ["0", "1", "0", "u", "0", "v"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Use the chain 0≤w≤v≤u≤1.", "Each inner variable is at most its next outer neighbor."], "id": "w03-p4-c", "label": "c"}], "solution": ["The volume element is $1000\\,du\\,dv\\,dw$; the normalized solid has volume $1/6$.", "$M=1000\\int_0^1\\int_0^u\\int_0^v e^{u^3}\\,dw\\,dv\\,du=500\\int_0^1u^2e^{u^3}\\,du$.", "With $a=u^3$, $M=(500/3)[e^a]_0^1=1000(e-1)/6$ kg. Integrating u first would require a non-elementary antiderivative of $e^{u^3}$."], "reflection": "Write a second valid order and check that no inner bound depends on a variable already integrated.", "extension": false, "discussionSolution": "Another order is $dv\\,dw\\,du$, with $0\\le u\\le1$, $0\\le w\\le u$, $w\\le v\\le u$. The corresponding inner limits depend only on outer variables.", "id": "w03-p4"}, {"title": "A day of San Lorenzo River flow", "context": "The historical USGS table gives March 1, 2000 daily mean discharge $755$ ft$^3$/s. Assume a constant rectangular cross-section $10$ m wide and $2$ m deep and plug flow with the same daily discharge. Use $86400$ seconds per day.", "model": "Daily mean Q is measured. Cross-section, plug flow, and within-day constant speed are assumptions; no observed spatial velocity is supplied.", "sources": ["river"], "work": "Convert discharge first. Describe a swept box of length speed × time, then integrate 1 over that box.", "questions": [{"prompt": "Find the model plug-flow speed on March 1.", "expected": "755*0.028316846592/20", "units": "m/s", "kind": "number", "tolerance": 1e-05, "hints": ["Convert cubic feet per second to cubic meters per second.", "Divide by the assumed 20 m² cross-section."], "id": "w03-p5-a", "label": "a"}, {"prompt": "Find the March 1 transported volume.", "expected": "755*0.028316846592*86400", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Discharge is volume per time.", "Multiply the daily mean by 86,400 seconds."], "id": "w03-p5-b", "label": "b"}, {"prompt": "Find total transported volume for March 1–4 using the four daily means.", "expected": "(755+614+539+475)*0.028316846592*86400", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["These are four equal one-day intervals.", "Sum their mean discharges, then convert and multiply by seconds per day."], "id": "w03-p5-c", "label": "c"}], "solution": ["$Q_1=755(0.028316846592)$ m$^3$/s. The assumed speed is $U=Q_1/20$.", "The swept box is $0\\le x\\le86400U$, $0\\le y\\le10$, $0\\le z\\le2$. Its volume is $20(86400U)=86400Q_1$.", "For the four days, $V=86400(0.028316846592)(755+614+539+475)$. Daily means determine each day’s total even when the real instantaneous flow varies."], "reflection": "Which answers depend on the assumed cross-section, and which follow directly from discharge data?", "extension": true, "discussionSolution": "The inferred speed depends on the assumed cross-section. Each daily volume and their four-day sum follow from the published daily mean discharges and do not require plug flow.", "id": "w03-p5"}]}, {"week": 4, "title": "Changing coordinates in coastal models", "subtitle": "Stretch Marks: How Maps Distort Area", "skills": ["Map boundaries into new coordinates", "Invert a linear transformation", "Compute and orient a Jacobian correctly", "Use polar coordinates on an ellipse", "Check whether a nonlinear map overlaps"], "formulas": ["$\\iint_D f\\,dx\\,dy=\\iint_{D^*}f(T(u,v))|\\det DT|\\,du\\,dv$", "$x=r\\cos\\theta,\\ y=r\\sin\\theta,\\ dA=r\\,dr\\,d\\theta$"], "sources": ["reserve", "aquarium", "noaa", "rover"], "problems": [{"title": "An equal-area Younger Lagoon model", "context": "The reserve reports $72$ acres. Use $1$ acre $=4046.8564224$ m$^2$ and let $A=72(4046.8564224)$. Model the reserve by an ellipse with semiaxes $a=\\sqrt{2A/\\pi}$ and $b=\\sqrt{A/(2\\pi)}$. Use $x=au$, $y=bv$.", "model": "Area is published; the ellipse and axis ratio 2 are chosen for teaching, not surveyed boundaries.", "sources": ["reserve"], "work": "Find the transformed domain and Jacobian. For mass, assume density $1+(x/a)^2$ kg/m$^2$.", "questions": [{"prompt": "Find the constant absolute Jacobian.", "expected": "72*4046.8564224/pi", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Compute ab.", "The ellipse area is πab."], "id": "w04-p1-a", "label": "a"}, {"prompt": "Find the model ellipse area.", "expected": "72*4046.8564224", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["The transformed domain is a unit disk.", "Multiply π by the Jacobian."], "id": "w04-p1-b", "label": "b"}, {"prompt": "Find total modeled mass.", "expected": "5*72*4046.8564224/4", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["On the unit disk ∫1 dA=π and ∫u² dA=π/4.", "Multiply their sum by ab."], "id": "w04-p1-c", "label": "c"}], "solution": ["The ellipse maps to $u^2+v^2\\le1$, and $|J|=ab=A/\\pi$.", "Thus its physical area is $(A/\\pi)\\pi=A$ m$^2$.", "$M=(A/\\pi)\\iint_{u^2+v^2\\le1}(1+u^2)\\,du\\,dv$. Polar coordinates give $\\iint u^2=\\int_0^1r^3dr\\int_0^{2\\pi}\\cos^2\\theta\\,d\\theta=\\pi/4$, hence $M=5A/4$ kg."], "reflection": "Why is matching area insufficient to claim that the model captures the actual habitat shape?", "extension": false, "diagram": "ellipse", "discussionSolution": "Many differently shaped regions have the same area. Equal area does not recover the actual boundary, habitat types, or distribution of water and vegetation.", "id": "w04-p1"}, {"title": "A skewed exhibit sampling grid", "context": "Use half of the published $90$ ft and $52$ ft Open Sea dimensions to define $T(u,v)=(45u+26v,26v)$ feet on $[0,1]^2$.", "model": "This is an invented parallelogram sampling patch; it is not a map of the exhibit.", "sources": ["aquarium"], "work": "Map all four corners and sketch the parallelogram. Write the matrix, inverse, and determinant.", "questions": [{"prompt": "Enter the physical image of (1,1).", "expected": ["71", "26"], "units": "ft", "kind": "vector", "tolerance": 1e-05, "hints": ["Substitute both coordinates as 1.", "x=45+26 and y=26."], "id": "w04-p2-a", "label": "a"}, {"prompt": "Find the physical area of the patch.", "expected": "1170", "units": "ft²", "kind": "number", "tolerance": 1e-05, "hints": ["Area scales by the absolute determinant.", "The determinant is 45×26."], "id": "w04-p2-b", "label": "b"}, {"prompt": "Integrate the dimensionless index u+v over the physical patch.", "expected": "1170", "units": "index·ft²", "kind": "number", "tolerance": 1e-05, "hints": ["Transform both the index and the area.", "The average of u+v on the unit square is 1."], "id": "w04-p2-c", "label": "c"}], "solution": ["The corner images in boundary order are $(0,0),(45,0),(71,26),(26,26)$.", "$DT=\\begin{pmatrix}45&26\\\\0&26\\end{pmatrix}$ has determinant $1170$. The inverse is $v=y/26$, $u=(x-y)/45$.", "The index integral is $1170\\int_0^1\\int_0^1(u+v)\\,du\\,dv=1170$ index-ft$^2$."], "reflection": "Does a determinant determine the amount of shear, or only the signed area scaling?", "extension": false, "discussionSolution": "The determinant gives signed area scaling. Matrices with equal determinant can have very different shears, rotations, and stretches.", "id": "w04-p2"}, {"title": "Align coordinates with tide-model boundaries", "context": "Let $H=1.412-0.333=1.079$ m. In local dimensionless coordinates x,y a hypothetical footprint is bounded by $1\\le x+y\\le3$, $-1\\le x-y\\le1$. Physical coordinates have scale $10$ m, and depth is $H(x-y)^2/(x+y)$.", "model": "H is a datum difference. The boundaries, physical scale, and depth field are assumed.", "sources": ["noaa"], "work": "Use u=x+y and v=x-y. Write the inverse and distinguish forward from inverse Jacobians.", "questions": [{"prompt": "Enter x(u,v), y(u,v).", "expected": ["(u+v)/2", "(u-v)/2"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Add and subtract the coordinate definitions.", "The two inverse equations each have a factor 1/2."], "id": "w04-p3-a", "label": "a"}, {"prompt": "Find the absolute inverse Jacobian for normalized x,y.", "expected": "1/2", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["The forward determinant is -2.", "Use the reciprocal, then absolute value."], "id": "w04-p3-b", "label": "b"}, {"prompt": "Find physical water volume.", "expected": "100*1.079*log(3)/3", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["The physical area factor is 100×1/2.", "Integrate v²/u over 1≤u≤3, -1≤v≤1."], "id": "w04-p3-c", "label": "c"}], "solution": ["$x=(u+v)/2$, $y=(u-v)/2$ give $J=-1/2$ and a rectangular new domain.", "Physical area is $100(1/2)\\,du\\,dv$. The integrand becomes $Hv^2/u$.", "$V=50H\\int_1^3\\int_{-1}^1v^2/u\\,dv\\,du=50H(2/3)\\ln3=100H\\ln3/3$ m$^3$."], "reflection": "Why is there no singularity in 1/u on this region?", "extension": false, "discussionSolution": "The transformed coordinate u ranges from 1 to 3 and never reaches zero, so 1/u remains bounded.", "id": "w04-p3"}, {"title": "A nonlinear rover swath", "context": "Use rover-derived scales $a=2.6$ m and $b=1.7$ m in $T(u,v)=(a(u^2-v^2),2buv)$ on $0\\le u,v\\le1$.", "model": "The equipment dimensions are published; this transformation is an invented survey swath.", "sources": ["rover"], "work": "Map the four boundary edges and check injectivity on the square before applying change of variables.", "questions": [{"prompt": "Enter the signed Jacobian as a function of u,v.", "expected": "4*2.6*1.7*(u^2+v^2)", "units": "m²", "kind": "expression", "tolerance": 1e-05, "hints": ["Differentiate both output coordinates.", "Subtract (−2av)(2bu) from (2au)(2bv)."], "id": "w04-p4-a", "label": "a"}, {"prompt": "Find image area.", "expected": "8*2.6*1.7/3", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate the Jacobian over the unit square.", "Each of ∫u² and ∫v² contributes 1/3."], "id": "w04-p4-b", "label": "b"}, {"prompt": "Which statement justifies counting the image once?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Compare T(u,v) with T(−u,−v).", "In first-quadrant polar coordinates the map doubles angles from [0,π/2] into [0,π]."], "options": ["The map is one-to-one on all of R².", "The map is one-to-one on the first quadrant, although it is not globally one-to-one.", "The absolute Jacobian alone prevents overlaps."], "id": "w04-p4-c", "label": "c"}], "solution": ["$J=(2au)(2bu)-(-2av)(2bv)=4ab(u^2+v^2)$. It vanishes only at the origin.", "After undoing the positive x,y scalings, the map squares polar radius and doubles angle. There are no overlaps in the first quadrant; globally opposite inputs have equal outputs.", "$A=4ab\\int_0^1\\int_0^1(u^2+v^2)\\,du\\,dv=8ab/3$ m$^2$."], "reflection": "What goes wrong if the same area formula is applied to a domain containing both a point and its negative?", "extension": false, "discussionSolution": "Opposite nonzero inputs have the same image. Integrating the absolute Jacobian over both copies would count overlapping image area twice.", "id": "w04-p4"}, {"title": "Hyperbolic sampling boundaries", "context": "A hypothetical coastal patch in meter coordinates lies in the first quadrant with $1\\le xy\\le3$ and $1\\le y/x\\le4$. Let $u=xy$, $v=y/x$, and use a synthetic loading $c=0.333xy$ g/m$^2$; the numerical coefficient is chosen from NOAA’s MLW datum.", "model": "Only the numerical scale 0.333 comes from the source. It does not imply a measured relation between tide height and sediment loading; coefficients carry the required units.", "sources": ["noaa"], "work": "Find the unique positive inverse and compute the easier forward determinant first.", "questions": [{"prompt": "Enter the absolute inverse Jacobian in u,v.", "expected": "1/(2*v)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Use u_x=y, u_y=x, v_x=−y/x², v_y=1/x.", "The forward determinant is 2v."], "id": "w04-p5-a", "label": "a"}, {"prompt": "Find patch area.", "expected": "2*log(2)", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate 1/(2v) over 1≤u≤3 and 1≤v≤4.", "The u interval has length 2."], "id": "w04-p5-b", "label": "b"}, {"prompt": "Find total synthetic loading.", "expected": "4*0.333*log(2)", "units": "g", "kind": "number", "tolerance": 1e-05, "hints": ["The transformed density is 0.333u.", "The u integral is 4 and the v integral is log(4)."], "id": "w04-p5-c", "label": "c"}], "solution": ["Positivity gives $x=\\sqrt{u/v}$, $y=\\sqrt{uv}$, so the transformation is one-to-one here.", "The forward Jacobian is $2y/x=2v$, and $|J_{\\rm inverse}|=1/(2v)$. Area is $\\int_1^4\\int_1^3(2v)^{-1}\\,du\\,dv=\\ln4=2\\ln2$ m$^2$.", "The loading is $0.333\\int_1^4\\int_1^3u/(2v)\\,du\\,dv=4(0.333)\\ln2$ g."], "reflection": "Why is the first-quadrant restriction essential for the inverse?", "extension": true, "discussionSolution": "For positive u,v, the first-quadrant condition chooses the positive square roots. Without a sign restriction, the same u,v can correspond to two opposite points.", "id": "w04-p5"}]}, {"week": 5, "title": "Balance points, spherical models, and singularities", "subtitle": "The Balancing Act", "skills": ["Compute density-weighted moments", "Exploit symmetry before integrating", "Choose cylindrical or spherical bounds", "Define improper integrals by limits", "Check absolute integrability before interchanging"], "formulas": ["$\\bar z=\\frac{\\iiint z\\delta\\,dV}{\\iiint\\delta\\,dV}$", "$dV=r\\,dr\\,d\\theta\\,dz=\\rho^2\\sin\\phi\\,d\\rho\\,d\\phi\\,d\\theta$"], "sources": ["reserve", "aquarium", "rover", "noaa"], "problems": [{"title": "A habitat-loading balance point", "context": "Use $x=50u$, $y=50v$ meters on $-1\\le u\\le1$, $u^2\\le v\\le1$. Compare uniform density 1 kg/m$^2$ with density v kg/m$^2$.", "model": "This parabolic habitat patch and both densities are teaching models, not measured reserve distributions.", "sources": ["reserve"], "work": "Sketch the patch, use reflection to determine the x-coordinate, and write mass and y-moment integrals for each density.", "questions": [{"prompt": "Find mass with uniform density.", "expected": "10000/3", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["dA=2,500 du dv.", "The normalized area is 4/3."], "id": "w05-p1-a", "label": "a"}, {"prompt": "Find physical mean y for uniform density.", "expected": "30", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["The normalized v moment is 4/5.", "Divide by normalized mass 4/3, then multiply by 50."], "id": "w05-p1-b", "label": "b"}, {"prompt": "Find physical mean y when density is v.", "expected": "250/7", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Mass is proportional to ∫v=4/5.", "The next moment is ∫v²=4/7."], "id": "w05-p1-c", "label": "c"}], "solution": ["Reflection $u\\mapsto-u$ preserves both densities, so $\\bar x=0$. Uniform mass is $2500\\int_{-1}^1(1-u^2)du=10000/3$ kg.", "For uniform density, $\\bar v=(4/5)/(4/3)=3/5$, hence $\\bar y=50(3/5)=30$ m.", "For density v, $\\bar v=(4/7)/(4/5)=5/7$, hence $\\bar y=250/7$ m. More weight near the top raises the balance point."], "reflection": "Why does a common coordinate-area factor cancel from the center-of-mass ratio?", "extension": false, "discussionSolution": "Both mass and moment contain the same area-scaling factor 2500, so it cancels. The extra length factor 50 in the physical y coordinate does not cancel.", "id": "w05-p1"}, {"title": "A cone inside an exhibit-scale model", "context": "The Kelp Forest exhibit is published as 28 ft tall. Model a solid cone with tip at z=0, height h=28 ft, and invented base radius R=5 ft.", "model": "The height is source-derived; the cone is not an actual exhibit feature. Density coefficients below use feet consistently.", "sources": ["aquarium"], "work": "Describe the cone cylindrically in two orders. Compute uniform volume and height moment. Then use density 1+z/h lb/ft³ for a new mass calculation.", "questions": [{"prompt": "Find cone volume.", "expected": "700*pi/3", "units": "ft³", "kind": "number", "tolerance": 1e-05, "hints": ["At height z, radius is Rz/h.", "Integrate πR²z²/h² over 0≤z≤h."], "id": "w05-p2-a", "label": "a"}, {"prompt": "Find uniform center-of-mass height.", "expected": "21", "units": "ft", "kind": "number", "tolerance": 1e-05, "hints": ["The height moment is πR²h²/4.", "Divide by πR²h/3."], "id": "w05-p2-b", "label": "b"}, {"prompt": "Find mass for density 1+z/h.", "expected": "1225*pi/3", "units": "lb", "kind": "number", "tolerance": 1e-05, "hints": ["Multiply each horizontal slice area by 1+z/h.", "The dimensionless radial-height integral gives 1/3+1/4=7/12."], "id": "w05-p2-c", "label": "c"}], "solution": ["Cylindrical bounds are $0\\le z\\le h$, $0\\le r\\le Rz/h$, $0\\le\\theta\\le2\\pi$; equivalently $(h/R)r\\le z\\le h$, $0\\le r\\le R$.", "$V=\\pi R^2h/3=700\\pi/3$ ft$^3$, and $N_z=\\pi R^2h^2/4$. Thus $\\bar z=3h/4=21$ ft.", "For the variable density, $M=(\\pi R^2/h^2)\\int_0^h(z^2+z^3/h)dz=7\\pi R^2h/12=1225\\pi/3$ lb."], "reflection": "Why is the uniform center closer to the base than to the tip?", "extension": false, "diagram": "cone", "discussionSolution": "Horizontal cross-section area is proportional to z². More mass lies near the broad base, giving a balance point 3h/4 above the tip.", "id": "w05-p2"}, {"title": "A spherical instrument model", "context": "Use an invented spherical chamber of radius a=1.5 m, a scale taken from the rover’s reported height. In the full ball set density $e^{(\\rho/a)^3}$ kg/m$^3$. Separately consider the uniform part above $z=\\sqrt{x^2+y^2}$.", "model": "The spherical chamber and densities are hypothetical; the rover is not spherical.", "sources": ["rover"], "work": "Give complete spherical bounds for the ball and for the cone-bounded sector. Distinguish volume from surface area.", "questions": [{"prompt": "Find full-ball mass for the exponential density.", "expected": "4.5*pi*(e-1)", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["Set w=(ρ/a)^3.", "The two angular integrals supply 4π."], "id": "w05-p3-a", "label": "a"}, {"prompt": "Find uniform sector volume.", "expected": "1.125*pi*(2-sqrt(2))", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["The cone is φ=π/4.", "Integrate ρ²sinφ over 0≤ρ≤a and all azimuths."], "id": "w05-p3-b", "label": "b"}, {"prompt": "Find the uniform sector center-of-mass height.", "expected": "9*(2+sqrt(2))/32", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Multiply dV by ρcosφ for the moment.", "The unit-radius answer is 3(2+sqrt(2))/16, then scale by a."], "id": "w05-p3-c", "label": "c"}], "solution": ["For the ball use $0\\le\\rho\\le a$, $0\\le\\phi\\le\\pi$, $0\\le\\theta\\le2\\pi$. The radial substitution gives $M=4\\pi a^3(e-1)/3$.", "The sector has $0\\le\\phi\\le\\pi/4$. Its volume is $\\pi a^3(2-\\sqrt2)/3$.", "The height moment is $\\pi a^4/8$. Dividing by the sector volume gives $3a(2+\\sqrt2)/16=9(2+\\sqrt2)/32$ m."], "reflection": "Why is it necessary to multiply by an additional ρ when computing the height moment?", "extension": false, "discussionSolution": "The volume element already contains ρ²; height z=ρcosφ contributes another ρ. Moments weight mass by coordinate, rather than just adding mass.", "id": "w05-p3"}, {"title": "A Gaussian coastal sensor footprint", "context": "An invented sensitivity model is $f(x,y)=\\exp(-(x^2+y^2)/\\sigma^2)$ with $\\sigma=50$ m. Consider the whole plane and a disk of radius 100 m.", "model": "The coastal-monitoring context is real, but this Gaussian response and scale are assumptions; f is an unnormalized index.", "sources": ["noaa"], "work": "Evaluate on a finite disk first and take a limit. Use square exhaustion to connect the two-dimensional result with a one-dimensional Gaussian.", "questions": [{"prompt": "Find the index integral on the 100 m disk.", "expected": "2500*pi*(1-exp(-4))", "units": "index·m²", "kind": "number", "tolerance": 1e-05, "hints": ["Use polar coordinates.", "The radial antiderivative is −σ² exp(−r²/σ²)/2."], "id": "w05-p4-a", "label": "a"}, {"prompt": "Find the whole-plane index integral.", "expected": "2500*pi", "units": "index·m²", "kind": "number", "tolerance": 1e-05, "hints": ["Let disk radius tend to infinity.", "Nonnegativity makes exhaustion appropriate."], "id": "w05-p4-b", "label": "b"}, {"prompt": "Find $\\int_{-\\infty}^{\\infty}e^{-(x/50)^2}\\,dx$.", "expected": "50*sqrt(pi)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["On a square the two-variable integrand factors.", "Take the positive square root of the whole-plane result."], "id": "w05-p4-c", "label": "c"}], "solution": ["$I(R)=2\\pi\\int_0^R e^{-r^2/\\sigma^2}r\\,dr=\\pi\\sigma^2(1-e^{-R^2/\\sigma^2})$. Set R=100 and σ=50 for part (a).", "As R tends to infinity, $I(R)\\to\\pi\\sigma^2=2500\\pi$.", "Square exhaustion gives $(\\int_{-\\infty}^{\\infty}e^{-(x/50)^2}dx)^2=2500\\pi$. The positive integral is $50\\sqrt\\pi$."], "reflection": "Why is 2500π not a probability? What factor would normalize the two-dimensional index?", "extension": false, "discussionSolution": "The sensitivity index is not normalized. Multiplication by $1/(2500\\pi)$ makes its whole-plane integral equal 1 and gives the density units m$^{-2}$.", "id": "w05-p4"}, {"title": "When a singular model stops making sense", "context": "In dimensionless local coordinates, compare a hypothetical concentration $r^{-3/2}$ with the signed field $g(x,y)=(x^2-y^2)/(x^2+y^2)^2$ on $(0,1]^2$.", "model": "These are diagnostic analytical models, not observed coastal concentrations. Negative g is a signed balance, not a physical mass density.", "sources": ["noaa"], "work": "Use cutoff annuli for the radial model and test absolute integrability before swapping the two integrals of g.", "questions": [{"prompt": "Where is the integral of $r^{-3/2}$ finite?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Include the polar area factor r.", "The radial integrand is r^(−1/2)."], "options": ["Both near zero and outside the unit disk.", "Only on the punctured unit disk.", "Only outside the unit disk.", "Neither."], "id": "w05-p5-a", "label": "a"}, {"prompt": "Find its integral on the punctured unit disk.", "expected": "4*pi", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Compute 2π∫₀¹r^(−1/2)dr.", "The radial integral is 2."], "id": "w05-p5-b", "label": "b"}, {"prompt": "Enter the two iterated integrals of g: first $dy\\,dx$, then $dx\\,dy$.", "expected": ["pi/4", "-pi/4"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Differentiate y/(x²+y²) with respect to y.", "Interchanging x,y negates g."], "id": "w05-p5-c", "label": "c"}], "solution": ["Near zero, $\\int r^{-3/2}dA=2\\pi\\int_0^1r^{-1/2}dr=4\\pi$; at infinity the same antiderivative diverges.", "$\\partial_y[y/(x^2+y^2)]=g$. Thus the dy-first integral is $\\int_0^1(1+x^2)^{-1}dx=\\pi/4$. Antisymmetry gives the reverse order $-\\pi/4$.", "In polar coordinates $|g|=|\\cos2\\theta|/r^2$. On a first-quadrant annulus its integral is $\\ln(1/\\varepsilon)$, which diverges. Absolute integrability fails, so Fubini cannot justify the interchange."], "reflection": "State the general near-zero integrability threshold for 1/r^s in two and three dimensions.", "extension": true, "discussionSolution": "For 1/r^s, near-zero integrability requires s<2 in two dimensions and s<3 in three dimensions. Equality gives logarithmic divergence. At infinity the inequalities reverse.", "id": "w05-p5"}]}, {"week": 6, "title": "Paths, work, and route independence", "subtitle": "The Road Not Taken (Doesn’t Matter)", "skills": ["Compute scalar path integrals with speed", "Handle reparametrization and reversal", "Evaluate work with a dot product", "Find and verify a potential", "Recognize global domain obstructions"], "formulas": ["$\\int_C f\\,ds=\\int_a^b f(c(t))\\|c\\prime(t)\\|dt$", "$\\int_C\\mathbf F\\cdot d\\mathbf r=\\int_a^b\\mathbf F(c(t))\\cdot c\\prime(t)dt$", "$\\int_C\\nabla f\\cdot d\\mathbf r=f(B)-f(A)$"], "sources": ["rover", "mars", "pump"], "problems": [{"title": "A rover-scale sampling transect", "context": "Use a straight transect from $(0,0)$ to $(2.6,1.7)$ m, based on the rover’s published dimensions. Model wire density along it by $\\lambda(x,y)=1+x/2.6$ kg/m.", "model": "Endpoints and density define an invented calibration wire, not an observed rover route.", "sources": ["rover"], "work": "Parametrize the segment in two ways, compute speed, and include it in both mass and coordinate-moment integrals.", "questions": [{"prompt": "Find transect length.", "expected": "sqrt(2.6^2+1.7^2)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Use the norm of (2.6,1.7).", "The squared length is 9.65."], "id": "w06-p1-a", "label": "a"}, {"prompt": "Find wire mass.", "expected": "1.5*sqrt(9.65)", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["Use c(t)=(2.6t,1.7t), 0≤t≤1.", "Density becomes 1+t and speed is constant."], "id": "w06-p1-b", "label": "b"}, {"prompt": "Find the wire center-of-mass x coordinate.", "expected": "13/9", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["The x moment includes 2.6t(1+t).", "The ratio of ∫t(1+t) to ∫(1+t) is 5/9."], "id": "w06-p1-c", "label": "c"}], "solution": ["$c(t)=(2.6t,1.7t)$ has speed $L=\\sqrt{9.65}$. With $c(s)=(2.6s^2,1.7s^2)$, speed is $2sL$ and the same geometric integral results.", "$M=L\\int_0^1(1+t)dt=3L/2$ kg.", "$N_x=2.6L\\int_0^1t(1+t)dt=2.6L(5/6)$. Thus $\\bar x=N_x/M=2.6(5/9)=13/9$ m."], "reflection": "Why does reversing this wire not negate its mass?", "extension": false, "discussionSolution": "Mass uses the speed norm, which stays nonnegative when traversal reverses. Work uses the oriented velocity vector and changes sign.", "id": "w06-p1"}, {"title": "A descent to the MARS depth", "context": "MBARI reports the MARS node at 891 m depth. For a toy descent use $c(t)=(100t,0,-891t)$ m, $0\\le t\\le1$. A cable on this path has density $1-z/891$ kg/m; a constant downward force is $(0,0,-2)$ N.", "model": "Only the depth is published. The 100 m offset, straight cable, density, and force are assumed; this is not the actual MARS cable.", "sources": ["mars"], "work": "Compute speed once, then distinguish the scalar mass integral from the force-work integral.", "questions": [{"prompt": "Find path length.", "expected": "sqrt(803881)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["The velocity is (100,0,−891).", "Length is its norm over a unit t interval."], "id": "w06-p2-a", "label": "a"}, {"prompt": "Find cable mass.", "expected": "1.5*sqrt(803881)", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["Density becomes 1+t.", "Use the positive speed, not a signed vertical derivative."], "id": "w06-p2-b", "label": "b"}, {"prompt": "Find work of the downward force during descent.", "expected": "1782", "units": "J", "kind": "number", "tolerance": 1e-05, "hints": ["Dot (0,0,−2) with (100,0,−891).", "Both vertical signs are negative."], "id": "w06-p2-c", "label": "c"}], "solution": ["$c\\prime=(100,0,-891)$, so speed is $\\sqrt{10000+891^2}=\\sqrt{803881}$ m per unit parameter.", "$M=\\sqrt{803881}\\int_0^1(1+t)dt=3\\sqrt{803881}/2$ kg.", "$W=\\int_0^1(0,0,-2)\\cdot(100,0,-891)dt=1782$ J. Reversing direction negates W but preserves M."], "reflection": "How could the force do positive work even though the final z coordinate is negative?", "extension": false, "discussionSolution": "Both the downward force and downward displacement have negative z components. Their dot product is positive, indicating force in the direction of motion.", "id": "w06-p2"}, {"title": "Circulation around a modeled current", "context": "In a hypothetical horizontal current near an intake use $\\mathbf v=(-ay,ax)$ with $a=0.001$ s$^{-1}$. Let C be the radius-100 m circle, counterclockwise.", "model": "The Aquarium intake context is real; this rotating field, its rate, and loop radius are invented, not pump measurements.", "sources": ["pump"], "work": "Parametrize C, calculate the dot product, and compare with the radial field $(ax,ay)$.", "questions": [{"prompt": "Find counterclockwise circulation.", "expected": "20*pi", "units": "m²/s", "kind": "number", "tolerance": 1e-05, "hints": ["Use c(t)=(100cos t,100sin t).", "The dot product is aR²=10."], "id": "w06-p3-a", "label": "a"}, {"prompt": "Find clockwise circulation for the same field.", "expected": "-20*pi", "units": "m²/s", "kind": "number", "tolerance": 1e-05, "hints": ["Orientation matters for work-type integrals.", "Reverse the sign of the previous answer."], "id": "w06-p3-b", "label": "b"}, {"prompt": "Find circulation of the radial field (ax,ay) on the same circle.", "expected": "0", "units": "m²/s", "kind": "number", "tolerance": 1e-05, "hints": ["Radial vectors are perpendicular to tangents.", "The integrand vanishes pointwise."], "id": "w06-p3-c", "label": "c"}], "solution": ["For radius R, $c\\prime=(-R\\sin t,R\\cos t)$ and $\\mathbf v(c)=a c\\prime$. Thus the dot product is $aR^2$.", "$\\Gamma=\\int_0^{2\\pi}aR^2dt=2\\pi aR^2=20\\pi$ m$^2$/s. Reversal gives $-20\\pi$.", "The radial field is perpendicular to $c\\prime$, so its circulation is zero despite nonzero speed."], "reflection": "Explain why zero circulation does not imply motionless water.", "extension": false, "discussionSolution": "Uniform translation has zero circulation around a closed loop even with nonzero speed. Opposing local rotations may also cancel in a circulation integral.", "id": "w06-p3"}, {"title": "Two routes across a sampling patch", "context": "Normalize an invented rover-scale patch using $u=x/2.6$, $v=y/1.7$. Compare routes $(t,t)$ and $(t,t^2)$ for $0\\le t\\le1$. The nondimensional route-cost field is $\\mathbf F=(v^2,u)$; compare with $\\mathbf G=(v,u)$.", "model": "The coordinate scales are source-derived. These are synthetic cost fields in normalized coordinates, not measured forces or energies.", "sources": ["rover"], "work": "Compute both route costs directly. Then find a potential for G and explain what differing costs prove about F.", "questions": [{"prompt": "Find F cost along the straight route.", "expected": "5/6", "units": "cost units", "kind": "number", "tolerance": 1e-05, "hints": ["Use du=dv=dt.", "The integrand is t²+t."], "id": "w06-p4-a", "label": "a"}, {"prompt": "Find F cost along the curved route.", "expected": "13/15", "units": "cost units", "kind": "number", "tolerance": 1e-05, "hints": ["For v=t², dv=2t dt.", "The integrand is t⁴+2t²."], "id": "w06-p4-b", "label": "b"}, {"prompt": "Enter a potential for G as a function of u,v.", "expected": "u*v", "units": "", "kind": "potential", "tolerance": 1e-05, "hints": ["Integrate G1=v with respect to u.", "Differentiate your candidate with respect to v to check G2."], "id": "w06-p4-c", "label": "c"}], "solution": ["On the straight route, $\\int_0^1(t^2+t)dt=5/6$.", "On the parabola, $\\int_0^1(t^4+2t^2)dt=13/15$. Different answers with equal endpoints disprove path independence for F.", "$g(u,v)=uv$ has gradient G. Both route costs for G are $g(1,1)-g(0,0)=1$. Equal answers on two routes alone would not prove global path independence; the potential does."], "reflection": "What extra factor would be needed if a physical force field were expressed in the original x,y coordinates?", "extension": false, "discussionSolution": "The physical differentials are $dx=2.6\\,du$, $dy=1.7\\,dv$. For a physical force field, these scale the corresponding work terms. A dimensionless cost field defined in u,v is a different model.", "id": "w06-p4"}, {"title": "A potential shortcut and its limits", "context": "In a hypothetical three-dimensional test rig with endpoint $(2.6,1.7,1.5)$ m, let $\\mathbf F=(2xy+z,x^2,x)$ N, with coefficients carrying the necessary units. Start at the origin.", "model": "The endpoint uses rover dimensions. The force field and path are synthetic, not measured engineering loads.", "sources": ["rover"], "work": "Construct a potential by integrating F1 and retaining a function of y,z. Explain the theorem before substituting endpoints.", "questions": [{"prompt": "Enter one potential f(x,y,z).", "expected": "x^2*y+x*z", "units": "", "kind": "potential", "tolerance": 1e-05, "hints": ["Integrating in x gives x²y+xz+g(y,z).", "Matching F2 and F3 forces g to be constant."], "id": "w06-p5-a", "label": "a"}, {"prompt": "Find work along any piecewise smooth route between the given endpoints.", "expected": "15.392", "units": "J", "kind": "number", "tolerance": 1e-05, "hints": ["Use endpoint potential minus starting potential.", "Evaluate 2.6²×1.7+2.6×1.5."], "id": "w06-p5-b", "label": "b"}, {"prompt": "Find work around any closed curve for this field.", "expected": "0", "units": "J", "kind": "number", "tolerance": 1e-05, "hints": ["A potential is defined on all of R³.", "A closed route has identical endpoint potential values."], "id": "w06-p5-c", "label": "c"}], "solution": ["$f_x=2xy+z$ gives $f=x^2y+xz+g(y,z)$. Matching $f_y=x^2$ and $f_z=x$ makes g constant.", "$W=f(2.6,1.7,1.5)-f(0,0,0)=2.6^2(1.7)+2.6(1.5)=15.392$ J.", "Every closed-curve work integral is zero. By contrast the punctured-plane field $(-y,x)/(x^2+y^2)$ has equal cross-partials away from zero but circulation $2\\pi$ around zero, so domain hypotheses matter."], "reflection": "Why does equality of cross-partials alone fail to settle the punctured-plane example?", "extension": true, "discussionSolution": "The punctured plane is not simply connected. A loop encircling the missing point cannot contract within the domain, and equality of cross-partials is only a local condition.", "id": "w06-p5"}]}, {"week": 7, "title": "Surfaces people build and measure", "subtitle": "Pride and Parametrization", "skills": ["Build parametrizations of spheres, cylinders, graphs, and ruled surfaces, with domains", "Identify a surface from its parametrization and read its grid curves", "Find the parameters of a point, tangent vectors, normals, and tangent planes", "Compute area for graphs, polar domains, spheres, cones, and surfaces of revolution", "Tell coordinate singularities from geometric corners; area does not depend on the parametrization"], "formulas": ["$\\mathbf N=\\Phi_u\\times\\Phi_v,\\quad dS=\\|\\mathbf N\\|\\,du\\,dv$", "$z=g(x,y):\\quad dS=\\sqrt{1+g_x^2+g_y^2}\\,dx\\,dy$", "$A=2\\pi\\int_a^b f(x)\\sqrt{1+f'(x)^2}\\,dx$ for $y=f(x)$ rotated about the $x$-axis"], "sources": ["earth", "alma", "cooling", "zimbabwe", "iter"], "problems": [{"title": "How much of Earth is tropical?", "context": "The tropics, between latitudes $23.44^\\circ$ S and $23.44^\\circ$ N, are where the Sun can be directly overhead at some time of year. On a globe they look like a thin belt around the middle. How much of the planet do they really cover?", "model": "R and the tilt are published values. A perfect sphere ignores Earth’s slight polar flattening, and the enclosing cylinder is a geometric construction, not a physical object.", "sources": ["earth"], "work": "Write $\\Phi(\\phi,\\theta)$ for the sphere with its domain, and describe its grid curves (fixed $\\theta$; fixed $\\phi$) in geographic language. Explain why this chart fails to be regular at the poles even though Earth is not pointed there. Before computing, predict: if Earth is cut by parallel planes into ten slabs of equal thickness, which slab has the most surface area? Then parametrize the cylinder as $\\Psi(\\theta,z)=(R\\cos\\theta,R\\sin\\theta,z)$ and find its lateral area between heights $z_1<z_2$.", "questions": [{"prompt": "Enter $\\|\\Phi_\\phi\\times\\Phi_\\theta\\|$ as a function of phi.", "expected": "6371^2*sin(phi)", "units": "km²", "kind": "expression", "tolerance": 1e-05, "hints": ["The two tangent vectors are perpendicular, with lengths R and R sin φ.", "So the norm of the cross product is their product."], "id": "w07-p1-a", "label": "a"}, {"prompt": "Find the area of the part of the sphere between two horizontal planes a distance h apart (both planes cut the sphere). Enter it as a function of h.", "expected": "2*pi*6371*h", "units": "km²", "kind": "expression", "tolerance": 1e-05, "hints": ["With z = R cos φ, dz = −R sin φ dφ turns R² sin φ dφ dθ into R dz dθ.", "Your answer should not depend on where the band sits."], "id": "w07-p1-b", "label": "b"}, {"prompt": "What fraction of Earth’s surface lies in the tropics? Enter the exact value or a decimal rounded to two places.", "expected": "sin(23.44*pi/180)", "units": "", "kind": "number", "tolerance": 0.002, "hints": ["The tropics run from z = −R sin 23.44° to z = R sin 23.44°.", "Divide the band area by the whole sphere’s area 4πR²."], "id": "w07-p1-c", "label": "c"}], "solution": ["$\\Phi(\\phi,\\theta)=(R\\sin\\phi\\cos\\theta,R\\sin\\phi\\sin\\theta,R\\cos\\phi)$ on $0\\le\\phi\\le\\pi$, $0\\le\\theta\\le2\\pi$. Fixed $\\theta$ gives a meridian (a line of longitude); fixed $\\phi$ gives a parallel (a line of latitude $90^\\circ-\\phi$).", "$\\Phi_\\phi=(R\\cos\\phi\\cos\\theta,R\\cos\\phi\\sin\\theta,-R\\sin\\phi)$ and $\\Phi_\\theta=(-R\\sin\\phi\\sin\\theta,R\\sin\\phi\\cos\\theta,0)$ are perpendicular with lengths $R$ and $R\\sin\\phi$, so $\\|\\Phi_\\phi\\times\\Phi_\\theta\\|=R^2\\sin\\phi=6371^2\\sin\\phi$ km$^2$. It vanishes at $\\phi=0,\\pi$ because every meridian meets at a pole, just as longitude is undefined there. A different chart, such as the graph $z=\\sqrt{R^2-x^2-y^2}$ near the North Pole, is regular there, so the sphere itself is smooth.", "For a band $z_1\\le z\\le z_2$, substituting $z=R\\cos\\phi$ gives $\\int_0^{2\\pi}\\!\\int_{z_1}^{z_2}R\\,dz\\,d\\theta=2\\pi R(z_2-z_1)=2\\pi Rh$. The cylinder has $\\|\\Psi_\\theta\\times\\Psi_z\\|=R$, so its band also has area $2\\pi R(z_2-z_1)$: Archimedes’ hat-box theorem. All ten equal slabs have the same area, $4\\pi R^2/10$; the equator does not win.", "The tropics have $h=2R\\sin23.44^\\circ$, so the fraction is $\\dfrac{2\\pi R\\cdot2R\\sin23.44^\\circ}{4\\pi R^2}=\\sin23.44^\\circ\\approx0.398$. Almost 40% of Earth’s surface is tropical."], "reflection": "Lambert’s cylindrical equal-area map moves each point horizontally out to this cylinder and unrolls it. Why does that map show Greenland and Africa with correct relative areas, even though shapes near the poles look squashed?", "extension": false, "id": "w07-p1", "discussionSolution": "Every band and every longitude wedge keeps its area under horizontal projection onto the cylinder (the hat-box theorem applied to thin pieces), so every region keeps its area. Shapes still distort: at latitude L, east–west lengths are stretched by 1/cos L while north–south lengths shrink by cos L, and the product, area, is unchanged.", "modelSpec": {"data": ["Earth’s volumetric mean radius: $R=6371$ km", "Axial tilt: $23.44^\\circ$, which puts the tropics at latitudes $23.44^\\circ$ S to $23.44^\\circ$ N"], "assume": ["Earth is a perfect sphere (the real Earth is flattened at the poles by about 0.3%)", "The cylinder is an imaginary construction that touches the sphere all around the equator"], "model": ["Earth: the sphere $x^2+y^2+z^2=R^2$, $R=6371$ km", "Latitude $L$ sits at height $z=R\\sin L$, so the tropics are the band $|z|\\le R\\sin23.44^\\circ$", "Enclosing cylinder: $x^2+y^2=R^2$, $-R\\le z\\le R$"]}, "photo": {"alt": "Earth seen from Apollo 17, showing Africa and the tropical belt", "credit": "NASA / Apollo 17 crew", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:The_Earth_seen_from_Apollo_17.jpg", "file": "w07-p1.jpg"}, "figure": {"alt": "Side view of the sphere inside its enclosing cylinder, with the tropics band shaded and horizontal projection arrows", "caption": "The model: Earth as a sphere, the tropics as a band of height $h$, and the enclosing cylinder.", "file": "w07-p1"}}, {"title": "How much mirror does an ALMA antenna need?", "context": "ALMA, at 5000 m altitude in Chile’s Atacama Desert, links dozens of dish antennas into one radio telescope. Each 12 m dish is a precision mirror whose curved surface must be built from panels, so its builders need to know exactly how much surface it has.", "model": "Diameter and focal length are published design values. The model ignores the 0.75 m central hole and the gaps between panels; it is a geometric idealization, not a manufacturing drawing.", "sources": ["alma"], "work": "Parametrize the mirror two ways and give each domain: as a graph over the disk, $(x,y,(x^2+y^2)/19.2)$, and with polar coordinates in the domain. Say whether the area should include the flat aperture disk. Then turn the dish on its side: rotating the profile $y=\\sqrt{19.2x}$, $0\\le x\\le1.875$, about the $x$-axis traces the same mirror. Set up $A=2\\pi\\int y\\sqrt{1+y'^2}\\,dx$, explain why it converges even though $y'$ is unbounded at $x=0$, and confirm it gives the same area as part (b).", "questions": [{"prompt": "Enter the graph area factor $\\sqrt{1+g_x^2+g_y^2}$ as a function of r.", "expected": "sqrt(1+r^2/92.16)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["g_x = 2x/19.2 and g_y = 2y/19.2.", "Then g_x² + g_y² = r²/9.6² = r²/92.16."], "id": "w07-p2-a", "label": "a"}, {"prompt": "Find the area of the mirror surface (exact, or rounded to two decimal places).", "expected": "2*pi*92.16/3*((1+36/92.16)^(3/2)-1)", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["In polar coordinates, A = ∫₀^{2π}∫₀⁶ sqrt(1 + r²/92.16) r dr dθ.", "Substitute w = 1 + r²/92.16."], "id": "w07-p2-b", "label": "b"}, {"prompt": "In the surface-of-revolution setup, simplify the integrand $y\\sqrt{1+y'^2}$ as a function of x.", "expected": "sqrt(19.2*x+92.16)", "units": "m", "kind": "expression", "tolerance": 1e-05, "hints": ["y' = 19.2/(2y), so y²(1 + y'²) = y² + 19.2²/4.", "Replace y² by 19.2x."], "id": "w07-p2-c", "label": "c"}], "solution": ["Graph form: $(x,y,(x^2+y^2)/19.2)$ on $x^2+y^2\\le36$. Polar form: $(r\\cos\\theta,r\\sin\\theta,r^2/19.2)$ on $0\\le r\\le6$, $0\\le\\theta\\le2\\pi$. Only the curved mirror counts; the flat aperture disk is open sky.", "$g_x=x/9.6$ and $g_y=y/9.6$, so the factor is $\\sqrt{1+r^2/92.16}$. In polar coordinates the shadow element is also multiplied by $r$.", "$A=2\\pi\\int_0^6 r\\sqrt{1+r^2/92.16}\\,dr=\\frac{2\\pi(92.16)}{3}\\Big[(1+\\tfrac{36}{92.16})^{3/2}-1\\Big]\\approx123.515$ m$^2$, about 9% more than the $36\\pi\\approx113.097$ m$^2$ aperture.", "With $y=\\sqrt{19.2x}$, $y'=19.2/(2y)$ blows up at $x=0$, but $y\\sqrt{1+y'^2}=\\sqrt{y^2+92.16}=\\sqrt{19.2x+92.16}$ stays bounded, so the improper integral converges, and \\[A=2\\pi\\int_0^{1.875}\\sqrt{19.2x+92.16}\\,dx\\] gives the same area: area belongs to the surface, not to the parametrization."], "reflection": "Two different parameter domains gave the same area. What would go wrong, for the people ordering mirror panels, if area depended on the parametrization?", "extension": false, "id": "w07-p2", "discussionSolution": "Area is a property of the surface. Any two regular, one-to-one parametrizations are related by a change of variables whose Jacobian converts one area element exactly into the other. If area depended on the chart, the amount of aluminum to order would depend on the engineer’s choice of coordinates, which is absurd.", "modelSpec": {"data": ["Primary mirror diameter: $12$ m", "Primary focal length: $f=4.8$ m (focal ratio $f/D=0.4$)", "Central hole: $0.75$ m across"], "assume": ["The mirror is a perfect paraboloid, vertex at the origin, axis along $z$", "Panel gaps and the central hole are ignored"], "model": ["Mirror: $z=\\dfrac{r^2}{4f}=\\dfrac{r^2}{19.2}$ m over the disk $r\\le6$ m", "Rim depth: $z=36/19.2=1.875$ m", "Rays parallel to the axis reflect through the focus $(0,0,4.8)$"]}, "photo": {"alt": "Two ALMA dish antennas on the Chajnantor plateau in Chile", "credit": "Iztok Bončina / ALMA (ESO/NAOJ/NRAO)", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Two_ALMA_antennas_on_Chajnantor_(ib-alma22).jpg", "file": "w07-p2.jpg"}, "figure": {"alt": "Cross-section of the paraboloid mirror with incoming rays reflecting to the focus", "caption": "The model: a paraboloid of aperture 12 m, rim depth 1.875 m, and focus 4.8 m above the vertex.", "file": "w07-p2"}}, {"title": "Straight lines that build a curved cooling tower", "context": "Power-station cooling towers have a distinctive narrow waist. The natural-draft tower at Niederaussem, Germany, was described as the tallest cooling tower in the world when it was built, yet its curved concrete shell is only about 24 cm thick. Surprisingly, that curved shell is made entirely of straight lines.", "model": "Only the height and base diameter are published values. The narrowest radius, its height, and the exact hyperboloid shape are assumed; real towers are not exact hyperboloids.", "sources": ["cooling"], "work": "Eliminate $t$ and $s$ to identify the surface by an equation in $x,y,z$, and check the base radius and total height. Describe the grid curves: what is the curve with $s$ fixed, and with $t$ fixed? A survey marker sits at $P=(38,19,40)$. Find its parameters, then compute $\\Phi_t$, $\\Phi_s$, and the normal there. Finally, check your tangent plane using the upper half written as a graph, $z=c\\sqrt{(x^2+y^2)/a^2-1}$.", "questions": [{"prompt": "Enter the parameters (t, s) of the marker, with 0 ≤ s < 2π.", "expected": ["0.5", "0"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["The height z = ct gives t immediately.", "Do not use the polar angle of (38, 19). Test s = 0 in both the x and y equations."], "id": "w07-p3-a", "label": "a"}, {"prompt": "Enter $\\Phi_t\\times\\Phi_s$ at the marker.", "expected": ["-3040", "-1520", "722"], "units": "m²", "kind": "vector", "tolerance": 1e-05, "hints": ["At the marker, Φ_t = (0, 38, 80) and Φ_s = (−19, 38, 0).", "Expand the cross product one component at a time."], "id": "w07-p3-b", "label": "b"}, {"prompt": "Enter the tangent plane at the marker as z in terms of x and y.", "expected": "(80*x+40*y-3040)/19", "units": "m", "kind": "expression", "tolerance": 1e-05, "hints": ["Use N·(X − P) = 0 with P = (38, 19, 40).", "Divide N by 38 first, then solve for z."], "id": "w07-p3-c", "label": "c"}], "solution": ["$x^2+y^2=a^2[(\\cos s-t\\sin s)^2+(\\sin s+t\\cos s)^2]=a^2(1+t^2)$ and $t=z/c$, so $\\frac{x^2+y^2}{38^2}-\\frac{z^2}{80^2}=1$: a hyperboloid of one sheet. At $t=-\\sqrt3$ the radius is $38\\cdot2=76$ m, matching the base, and the height is $c(2.5-\\sqrt3+\\sqrt3)=200$ m.", "Fixing $s$ gives $a(\\cos s,\\sin s,0)+t(-a\\sin s,a\\cos s,c)$, a straight line. Fixing $t$ gives a horizontal circle of radius $a\\sqrt{1+t^2}$. The curved shell is woven from straight lines, so straight reinforcing bars can follow it.", "$z=40$ gives $t=0.5$. Then $\\cos s-0.5\\sin s=1$ and $\\sin s+0.5\\cos s=0.5$ force $s=0$, not the polar angle $\\arctan(1/2)$ of $(38,19)$.", "$\\Phi_t=(-a\\sin s,a\\cos s,c)=(0,38,80)$ and $\\Phi_s=(-a(\\sin s+t\\cos s),a(\\cos s-t\\sin s),0)=(-19,38,0)$, so $\\mathbf N=(-3040,-1520,722)=38(-80,-40,19)$.", "The plane is $-80(x-38)-40(y-19)+19(z-40)=0$, that is, $z=(80x+40y-3040)/19$. The graph formula gives $z_x=\\dfrac{c\\,x/a^2}{\\sqrt{(x^2+y^2)/a^2-1}}=\\dfrac{80}{19}$ and $z_y=\\dfrac{40}{19}$ at $P$: the same plane."], "reflection": "A second family, $\\big(a(\\cos s+t\\sin s),\\,a(\\sin s-t\\cos s),\\,ct\\big)$, traces the same surface. How many straight lines on the surface pass through each point, and why might builders care?", "extension": false, "id": "w07-p3", "discussionSolution": "Two: one from each family, so the hyperboloid is doubly ruled. Straight reinforcing bars or formwork can follow both families, giving a curved, buckling-resistant shell assembled from straight pieces.", "modelSpec": {"data": ["Height: $200$ m", "Base diameter: $152$ m, so base radius $76$ m", "Shell thickness: about $0.24$ m"], "assume": ["The shell is exactly the surface traced by $\\Phi$ below; real towers only approximate this shape", "Narrowest radius $a=38$ m and vertical scale $c=80$ m, chosen to match the base radius and height", "$z$ is measured from the narrowest level, so the ground is at $z=-80\\sqrt3\\approx-138.6$ m"], "model": ["Shell: $\\Phi(t,s)=\\big(a(\\cos s-t\\sin s),\\ a(\\sin s+t\\cos s),\\ ct\\big)$", "Domain: $0\\le s\\le2\\pi$, $-\\sqrt3\\le t\\le2.5-\\sqrt3$", "$a=38$ m, $c=80$ m"]}, "photo": {"alt": "The waisted concrete cooling tower of Niederaussem power station, Germany", "credit": "Stodtmeister", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Kraftwerk_Niederau%C3%9Fem_Block_K_BoA_K%C3%BChlturm.jpg", "file": "w07-p3.jpg"}, "figure": {"alt": "Hyperboloid tower drawn as two crossing families of straight lines, with the point P marked", "caption": "The model surface drawn only with straight lines from $\\Phi$ (teal and brown: the two families). Height 200 m, base radius 76 m, narrowest radius 38 m at $z=0$; the marker $P$ is orange.", "file": "w07-p3"}}, {"title": "The Conical Tower of Great Zimbabwe", "context": "Great Zimbabwe, a UNESCO World Heritage site, was the capital of a southern African kingdom that flourished between roughly the 11th and 15th centuries. Inside its Great Enclosure stands a solid Conical Tower, built of granite blocks without mortar. How much stone surface faces the outside world?", "model": "Height and base diameter are published approximate values; descriptions vary by about a metre. The top radius is assumed, the real tower is masonry rather than a perfect cone, and the full cone’s apex is imaginary.", "sources": ["zimbabwe"], "work": "Write the curved stone face as a graph $z=g(x,y)$ over its shadow, and show the graph area factor is constant. Explain why that makes the curved area a fixed multiple of the shadow’s area, just as for a tilted plane. Decide whether a lime-wash estimate for the curved face should include the flat top disk. Check your area with the cone formula $\\pi RL$, subtracting the missing tip.", "questions": [{"prompt": "Enter $\\Phi_u\\times\\Phi_v$ as a function of u and v.", "expected": ["6*u*cos(v)", "6*u*sin(v)", "u"], "units": "m", "kind": "vector", "tolerance": 1e-05, "hints": ["Φ_u = (cos v, sin v, −6) and Φ_v = (−u sin v, u cos v, 0).", "Check that the third component is positive."], "id": "w07-p4-a", "label": "a"}, {"prompt": "Where does Φ fail to be regular, and what does that mean for the tower?", "expected": "0", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Regularity fails exactly where the cross product is the zero vector.", "Its norm is u√37. Where is the apex, compared with the tower’s 9 m top?"], "options": ["Only at u = 0, the apex 7.5 m above the tower; the tower itself is regular everywhere.", "Along the top rim u = 1.25, where the tower is cut off.", "Along the seam v = 0, where the parametrization starts and ends.", "Nowhere: a cone has no special point."], "id": "w07-p4-b", "label": "b"}, {"prompt": "Find the area of the curved stone face, excluding the top disk.", "expected": "6*pi*sqrt(37)", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["‖N‖ = u√37.", "Integrate over 1.25 ≤ u ≤ 2.75 and 0 ≤ v ≤ 2π."], "id": "w07-p4-c", "label": "c"}], "solution": ["$\\Phi_u=(\\cos v,\\sin v,-6)$ and $\\Phi_v=(-u\\sin v,u\\cos v,0)$ give $\\mathbf N=(6u\\cos v,6u\\sin v,u)$ with $\\|\\mathbf N\\|=u\\sqrt{37}$, which is zero only at $u=0$.", "The apex $u=0$ is a genuine geometric corner, since no parametrization gives it a tangent plane, but it lies at $z=16.5$ m, outside the $9$ m tower. The truncated tower is regular everywhere; its top and bottom circles are boundary edges.", "$A=\\int_0^{2\\pi}\\int_{1.25}^{2.75}u\\sqrt{37}\\,du\\,dv=\\pi\\sqrt{37}\\,(2.75^2-1.25^2)=6\\pi\\sqrt{37}\\approx114.65$ m$^2$.", "As a graph, $z=16.5-6\\sqrt{x^2+y^2}$ has $g_x^2+g_y^2=36$, so the factor is the constant $\\sqrt{37}$ and $A=\\sqrt{37}\\times$ (annulus area $6\\pi$). Check: $\\pi RL-\\pi r\\ell=\\pi(2.75)(2.75\\sqrt{37})-\\pi(1.25)(1.25\\sqrt{37})=6\\pi\\sqrt{37}$. Lime-washing the flat top too would add $1.5625\\pi\\approx4.91$ m$^2$."], "reflection": "The sphere chart in the Earth problem also had a zero cross product at its poles. Why is that harmless for the sphere but a real corner for the cone?", "extension": false, "id": "w07-p4", "discussionSolution": "At a pole only the spherical-coordinate chart degenerates; another chart, such as a graph over the tangent plane, has a nonzero normal there, so the sphere is smooth. At a cone’s apex no parametrization gives a tangent plane, because normals from different sides point in different directions, so the corner is geometric.", "modelSpec": {"data": ["Height: about $9$ m (30 ft)", "Base diameter: about $5.5$ m (18 ft), so base radius $2.75$ m", "Published descriptions differ by about a metre"], "assume": ["The tower is a truncated cone with top radius $1.25$ m", "Its sloping side is extended upward to an imaginary apex so one formula describes it"], "model": ["Full cone: $\\Phi(u,v)=(u\\cos v,\\ u\\sin v,\\ 16.5-6u)$, $0\\le u\\le2.75$, $0\\le v\\le2\\pi$", "Tower: the part with $1.25\\le u\\le2.75$, that is, $0\\le z\\le9$ m", "The radius shrinks $1.5$ m over the $9$ m height, so $z$ falls $6$ m per metre of radius"]}, "photo": {"alt": "The Conical Tower inside the Great Enclosure at Great Zimbabwe", "credit": "Fanny Schertzer", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Conical_tower_%E2%80%93_Great_Zimbabwe.jpg", "file": "w07-p4.jpg"}, "figure": {"alt": "Side view of the truncated cone tower with dashed extension to an imaginary apex", "caption": "The model: a truncated cone, extended (dashed) to an imaginary apex where $\\Phi$ fails to be regular.", "file": "w07-p4"}}, {"title": "The plasma ring inside ITER", "context": "ITER, the international fusion experiment under construction in southern France, will hold a plasma hotter than the Sun’s core inside a ring-shaped magnetic cage. The shape of that ring is a torus.", "model": "Major and minor radii are published design values. The real plasma cross-section is D-shaped and taller than it is wide; a circular torus is a simplified model.", "sources": ["iter"], "work": "Describe the grid curves and what $R$ and $r$ measure. Show the two tangent vectors are perpendicular before computing the cross-product norm. Interpret the total area as (tube circumference) × (distance travelled by the tube’s center).", "questions": [{"prompt": "Enter $\\|\\Phi_\\theta\\times\\Phi_\\phi\\|$ as a function of phi.", "expected": "2*(6.2+2*cos(phi))", "units": "m²", "kind": "expression", "tolerance": 1e-05, "hints": ["The tangent lengths are R + r cos φ and r.", "The tangent vectors are perpendicular."], "id": "w07-p5-a", "label": "a"}, {"prompt": "Find the area of the model plasma surface.", "expected": "4*pi^2*6.2*2", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate r(R + r cos φ) over both angles.", "The cos φ term integrates to zero."], "id": "w07-p5-b", "label": "b"}, {"prompt": "Enter (area of the outer half, cos φ > 0) minus (area of the inner half).", "expected": "32*pi", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["The outer half has −π/2 ≤ φ ≤ π/2.", "Each half has area 2πr(πR ± 2r)."], "id": "w07-p5-c", "label": "c"}], "solution": ["Fixed $\\theta$ gives a circle of radius $r$, a cross-section of the tube; fixed $\\phi$ gives a horizontal circle of radius $R+r\\cos\\phi$. $R$ is the distance from the central axis to the tube’s center and $r$ is the tube’s radius.", "$\\Phi_\\theta=(-(R+r\\cos\\phi)\\sin\\theta,(R+r\\cos\\phi)\\cos\\theta,0)$ and $\\Phi_\\phi=(-r\\sin\\phi\\cos\\theta,-r\\sin\\phi\\sin\\theta,r\\cos\\phi)$ have zero dot product and lengths $R+r\\cos\\phi$ and $r$, so the norm is $r(R+r\\cos\\phi)=2(6.2+2\\cos\\phi)$ m$^2$.", "$A=\\int_0^{2\\pi}\\!\\int_0^{2\\pi}r(R+r\\cos\\phi)\\,d\\phi\\,d\\theta=4\\pi^2Rr=(2\\pi r)(2\\pi R)=49.6\\pi^2\\approx489.5$ m$^2$ (Pappus’ theorem).", "The outer half has area $2\\pi r(\\pi R+2r)$ and the inner half $2\\pi r(\\pi R-2r)$, a difference of $8\\pi r^2=32\\pi\\approx100.5$ m$^2$."], "reflection": "The same newsletter lists a plasma volume of 837 m³, while a circular torus with these radii has volume 2π²Rr² ≈ 490 m³. What feature of the real plasma explains the difference?", "extension": true, "id": "w07-p5", "discussionSolution": "Elongation. ITER’s plasma cross-section is D-shaped and about 1.7 times taller than it is wide, so it encloses much more volume than a circle of radius 2.0 m: 490 × 1.7 ≈ 833 m³, close to the published 837 m³. (In this model the volume and the area happen to share the number 49.6π², because V = A·r/2 and r/2 = 1 m.)", "modelSpec": {"data": ["Plasma major radius: $R=6.2$ m", "Plasma minor radius: $r=2.0$ m", "Plasma volume: $837$ m$^3$"], "assume": ["The plasma’s cross-section is a circle of radius $r$ (the real one is D-shaped and taller than it is wide)"], "model": ["Torus: $\\Phi(\\theta,\\phi)=\\big((R+r\\cos\\phi)\\cos\\theta,\\ (R+r\\cos\\phi)\\sin\\theta,\\ r\\sin\\phi\\big)$", "Domain: $0\\le\\theta\\le2\\pi$, $0\\le\\phi\\le2\\pi$"]}, "figure": {"alt": "Top view of the torus and a cut through its axis showing two circular tube cross-sections", "caption": "The model: a circular tube of radius $r$ whose centre runs around a circle of radius $R$.", "file": "w07-p5"}}]}, {"week": 8, "title": "Shell mass and flow through surfaces", "subtitle": "May the Flux Be With You", "skills": ["Evaluate scalar surface integrals", "Compute density-weighted shell moments", "Choose and verify orientation", "Distinguish unit normals from vector area", "Integrate nonuniform pipe flow"], "formulas": ["$\\iint_S f\\,dS=\\iint_D f(\\Phi)\\|\\Phi_u\\times\\Phi_v\\|du\\,dv$", "$\\iint_S\\mathbf F\\cdot\\mathbf n\\,dS=\\iint_D\\mathbf F(\\Phi)\\cdot(\\Phi_u\\times\\Phi_v)du\\,dv$"], "sources": ["rover", "pump"], "problems": [{"title": "Mass of a hemispherical instrument shell", "context": "A hypothetical upper hemispherical shell has radius a=1.5 m and constant surface density 2 kg/m$^2$. Its equator lies in z=0.", "model": "The housing shape and density are assumed; radius uses the rover’s reported height as a scale.", "sources": ["rover"], "work": "Use sphere coordinates and a scalar surface integral. Explain why no base disk is included in the mass.", "questions": [{"prompt": "Find shell mass.", "expected": "9*pi", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["Upper hemisphere area is 2πa².", "Multiply by surface density 2."], "id": "w08-p1-a", "label": "a"}, {"prompt": "Find the height moment $\\iint_S z\\delta\\,dS$.", "expected": "6.75*pi", "units": "kg·m", "kind": "number", "tolerance": 1e-05, "hints": ["Use z=a cosφ and dS=a² sinφ dφdθ.", "The angle integral of cosφ sinφ from 0 to π/2 is 1/2."], "id": "w08-p1-b", "label": "b"}, {"prompt": "Find center-of-mass height.", "expected": "0.75", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Divide height moment by mass.", "A uniform hemispherical shell has average height a/2."], "id": "w08-p1-c", "label": "c"}], "solution": ["$M=2(2\\pi a^2)=9\\pi$ kg. This is curved-shell mass, not a solid hemisphere or a shell with a flat lid.", "$N_z=2\\int_0^{2\\pi}\\int_0^{\\pi/2}a^3\\cos\\phi\\sin\\phi\\,d\\phi\\,d\\theta=2\\pi a^3=6.75\\pi$ kg-m.", "$\\bar z=N_z/M=a/2=0.75$ m. Horizontal bands have equal area for equal height increments."], "reflection": "Would reversing a chosen normal change this scalar mass integral?", "extension": false, "discussionSolution": "No. A scalar surface integral uses the norm of the area vector, so changing its direction does not change mass.", "id": "w08-p1"}, {"title": "A cylinder: coating and outward flux", "context": "Use a hypothetical cylinder side $x^2+y^2=0.25$, $0\\le z\\le1.5$ m. A coating index is $f=x^2+z$, with coefficients chosen so f is dimensionless. Separately let $\\mathbf F=(x,0,0)$ m/s, with coefficient 1 s$^{-1}$.", "model": "The height is rover-derived. Radius, coating index, and flow are models; exclude both end disks.", "sources": ["rover"], "work": "Use $\\Phi(\\theta,z)=(0.5\\cos\\theta,0.5\\sin\\theta,z)$. Compute both the vector area and its norm.", "questions": [{"prompt": "Find the scalar coating-index integral.", "expected": "21*pi/16", "units": "index·m²", "kind": "number", "tolerance": 1e-05, "hints": ["dS=0.5 dθdz.", "Replace x² by 0.25 cos²θ."], "id": "w08-p2-a", "label": "a"}, {"prompt": "Find outward flux of F through the side.", "expected": "3*pi/8", "units": "m³/s", "kind": "number", "tolerance": 1e-05, "hints": ["The outward unit normal is (cosθ,sinθ,0).", "Dot F with the vector area (0.5cosθ,0.5sinθ,0)."], "id": "w08-p2-b", "label": "b"}, {"prompt": "What is the orientation of $\\Phi_z\\times\\Phi_\\theta$?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Swapping cross-product order changes its sign.", "Φ_θ × Φ_z points outward."], "options": ["Outward.", "Inward.", "Undefined everywhere."], "id": "w08-p2-c", "label": "c"}], "solution": ["$\\Phi_\\theta\\times\\Phi_z=(0.5\\cos\\theta,0.5\\sin\\theta,0)$ has norm 0.5. Thus $\\iint f\\,dS=\\int_0^{1.5}\\int_0^{2\\pi}(0.25\\cos^2\\theta+z)(0.5)\\,d\\theta\\,dz=21\\pi/16$.", "Flux density in parameter coordinates is $(0.5\\cos\\theta,0,0)\\cdot(0.5\\cos\\theta,0.5\\sin\\theta,0)=0.25\\cos^2\\theta$. Integrating gives $3\\pi/8$ m$^3$/s.", "The reversed cross product points inward and negates a flux integral; its norm, and hence a scalar surface integral, stays unchanged."], "reflection": "Why would multiplying the flux integrand by another factor of 0.5 be an error?", "extension": false, "discussionSolution": "The vector area (0.5cosθ,0.5sinθ,0)dθdz already contains the surface-area factor 0.5. Multiplying by another 0.5 counts that scaling twice.", "id": "w08-p2"}, {"title": "Calibrate a nonuniform aquarium pipe flow", "context": "The Kelp Forest page reports pumps pushing up to 2,000 US gal/min. At that stated upper rate, model a circular pipe of radius R=0.1 m with axial speed $v(r)=U(1-r^2/R^2)$. Use 1 US gal=0.003785411784 m$^3$.", "model": "The upper rate is published. The pipe radius and parabolic profile are invented; U is inferred from this model, not measured.", "sources": ["pump"], "work": "Orient the cross-section downstream. Derive the flux integral, including the polar area factor, before solving for U.", "questions": [{"prompt": "Convert the stated upper flow to cubic meters per second.", "expected": "2000*0.003785411784/60", "units": "m³/s", "kind": "number", "tolerance": 1e-05, "hints": ["Convert gallons to cubic meters.", "Divide by 60 seconds per minute."], "id": "w08-p3-a", "label": "a"}, {"prompt": "Find model centerline speed U.", "expected": "2*(2000*0.003785411784/60)/(pi*0.1^2)", "units": "m/s", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate U(1−r²/R²)r over the disk.", "The flux is πR²U/2, not πR²U."], "id": "w08-p3-b", "label": "b"}, {"prompt": "Find signed flux if the normal is reversed.", "expected": "-2000*0.003785411784/60", "units": "m³/s", "kind": "number", "tolerance": 1e-05, "hints": ["The physical flow stays fixed.", "Reversing orientation negates the dot product."], "id": "w08-p3-c", "label": "c"}], "solution": ["$Q=2000(0.003785411784)/60=0.1261803928$ m$^3$/s.", "$Q=\\int_0^{2\\pi}\\int_0^R U(1-r^2/R^2)r\\,dr\\,d\\theta=\\pi R^2U/2$. Thus $U=2Q/(\\pi R^2)$, about 8.033 m/s.", "The cross-sectional mean speed is U/2. An upstream normal gives signed flux −Q."], "reflection": "Which part of this calculation would need real velocity measurements to test whether the assumed profile is suitable?", "extension": false, "diagram": "pipe", "discussionSolution": "A cross-sectional velocity survey would test the shape of the assumed profile and its centerline-to-mean relationship. A published total-flow capacity alone cannot determine the actual profile.", "id": "w08-p3"}, {"title": "Flow through a curved shelter", "context": "Use the shelter $z=g(x,y)=1.5-3(x^2+y^2)/8$ above z=0 and field $\\mathbf F=(y,-x,z)$ m/s, with coefficients 1 s$^{-1}$. Close it with its bottom disk.", "model": "This is the same hypothetical rover-scale shelter as Week 7. No measured water flow or actual shelter is claimed.", "sources": ["rover"], "work": "Use the upward graph vector area. Check that upward is outward for the cap and downward is outward for the base.", "questions": [{"prompt": "Find flux through the curved cap.", "expected": "3*pi", "units": "m³/s", "kind": "number", "tolerance": 1e-05, "hints": ["The graph vector area is (3x/4,3y/4,1)dA.", "The xy terms in the dot product cancel, leaving g."], "id": "w08-p4-a", "label": "a"}, {"prompt": "Find outward flux through the base.", "expected": "0", "units": "m³/s", "kind": "number", "tolerance": 1e-05, "hints": ["The base is z=0.", "Only the vertical field component can cross that disk."], "id": "w08-p4-b", "label": "b"}, {"prompt": "Find volume enclosed by cap and base.", "expected": "3*pi", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate height g over the radius-2 disk.", "Use 2π∫₀²(1.5−3r²/8)r dr."], "id": "w08-p4-c", "label": "c"}], "solution": ["$\\mathbf F(x,y,g)\\cdot(-g_x,-g_y,1)=y(3x/4)-x(3y/4)+g=g$.", "The cap flux is $2\\pi\\int_0^2(1.5-3r^2/8)r\\,dr=3\\pi$ m$^3$/s. On the downward base, $\\mathbf F\\cdot\\mathbf n=-z=0$.", "Volume uses the same height integral and is $3\\pi$ m$^3$. The numerical equality includes an implicit rate factor 1 s$^{-1}$; flux and volume have different units."], "reflection": "Why is numerical equality of flux and volume not an equality of physical quantities?", "extension": false, "discussionSolution": "Flux is a volume rate and has units m³/s; enclosed volume has units m³. Here the field coefficient 1 s⁻¹ makes the numerical values equal without equating their dimensions.", "id": "w08-p4"}, {"title": "A field whose total flux does not decay", "context": "On a sphere of radius a=1.5 m, consider $\\mathbf E=5(x,y,z)/(x^2+y^2+z^2)^{3/2}$. Separately use $\\mathbf G=0.001(x,y,z)$ and constant $\\mathbf H=(0,0,1)$. Coefficients carry the units needed for each field to represent velocity.", "model": "These are idealized vector fields around an imagined instrument, not actual seawater velocities.", "sources": ["rover"], "work": "Use outward unit normals. For H use only the upper hemisphere. Explain which source singularity blocks applying a volume theorem across the origin.", "questions": [{"prompt": "Find total outward E flux through the sphere.", "expected": "20*pi", "units": "m³/s", "kind": "number", "tolerance": 1e-05, "hints": ["On the sphere E·n=5/a².", "Multiply by 4πa²."], "id": "w08-p5-a", "label": "a"}, {"prompt": "Find total outward G flux through the sphere.", "expected": "27*pi/2000", "units": "m³/s", "kind": "number", "tolerance": 1e-05, "hints": ["On the sphere G·n=0.001a.", "Multiply by full sphere area."], "id": "w08-p5-b", "label": "b"}, {"prompt": "Find outward H flux through the upper hemisphere.", "expected": "9*pi/4", "units": "m³/s", "kind": "number", "tolerance": 1e-05, "hints": ["Use H·n=cosφ.", "The projected disk area is πa²."], "id": "w08-p5-c", "label": "c"}], "solution": ["$\\mathbf n=(x,y,z)/a$. Hence $\\mathbf E\\cdot\\mathbf n=5/a^2$ and total flux is $20\\pi$, independent of a.", "$\\mathbf G\\cdot\\mathbf n=0.001a$ gives $4\\pi(0.001)a^3=27\\pi/2000$.", "For H, integrate $a^2\\cos\\phi\\sin\\phi$ over the upper hemisphere to obtain $\\pi a^2=9\\pi/4$. E is undefined at the origin; a direct surface integral on a positive-radius sphere remains valid."], "reflection": "How does inverse-square decay exactly balance the growth of sphere area?", "extension": true, "discussionSolution": "Field magnitude decreases as 1/a² while sphere area increases as a². Their product is constant for every positive radius; the singular center cannot be included in a smooth-field volume theorem.", "id": "w08-p5"}]}, {"week": 9, "title": "Boundaries that reveal the interior", "subtitle": "It’s Not Easy Being Green", "skills": ["Orient outer and inner boundaries", "Check Green’s theorem directly", "Recover area from an outline", "Treat holes and singularities correctly", "Use the flux form and compare regions"], "formulas": ["$\\oint_{\\partial D}P\\,dx+Q\\,dy=\\iint_D(Q_x-P_y)\\,dA$", "$A=\\frac12\\oint_{\\partial D}(x\\,dy-y\\,dx)$", "$\\oint_{\\partial D}\\mathbf F\\cdot\\mathbf n\\,ds=\\iint_D\\nabla\\cdot\\mathbf F\\,dA$"], "sources": ["rover", "reserve", "pump"], "problems": [{"title": "Circulation around a rover-scale test patch", "context": "On a hypothetical $2.6$ m by $1.7$ m rectangle use $\\mathbf v=(-ay,ax)$ with $a=0.001$ s$^{-1}$. Traverse its boundary counterclockwise, starting along the bottom edge to the right.", "model": "Rectangle dimensions use the rover envelope; the planar current and its rate are assumed, not radar observations.", "sources": ["rover"], "work": "Parametrize all four edges, compute circulation directly, then use Green’s theorem. State its hypotheses.", "questions": [{"prompt": "Enter the four edge contributions in traversal order.", "expected": ["0", "0.00442", "0.00442", "0"], "units": "m²/s", "kind": "vector", "tolerance": 1e-05, "hints": ["Horizontal bottom flow contributes zero because y=0.", "Both the right and top edges contribute aLW."], "id": "w09-p1-a", "label": "a"}, {"prompt": "Find scalar curl v2_x−v1_y.", "expected": "0.002", "units": "s⁻¹", "kind": "number", "tolerance": 1e-05, "hints": ["Differentiate ax in x and −ay in y.", "Subtract a negative derivative."], "id": "w09-p1-b", "label": "b"}, {"prompt": "Find total counterclockwise circulation.", "expected": "0.00884", "units": "m²/s", "kind": "number", "tolerance": 1e-05, "hints": ["Add the four edge integrals.", "Or multiply 2a by area 2.6×1.7."], "id": "w09-p1-c", "label": "c"}], "solution": ["Use bottom $(2.6t,0)$, right $(2.6,1.7t)$, top $(2.6(1-t),1.7)$, left $(0,1.7(1-t))$, each $0\\le t\\le1$.", "The edge contributions are $0,a(2.6)(1.7),a(2.6)(1.7),0$, so circulation is $0.00884$ m$^2$/s.", "The field is smooth everywhere and the boundary is positive. Green gives $\\iint_D2a\\,dA=2(0.001)(4.42)=0.00884$."], "reflection": "For this field, would a different-shaped patch of equal area have the same circulation?", "extension": false, "diagram": "circulation", "discussionSolution": "Yes, for any admissible positive simple boundary in this smooth constant-curl field. Green’s theorem makes circulation equal to 2a times area, independent of shape.", "id": "w09-p1"}, {"title": "Area from a hypothetical restoration outline", "context": "The reserve reports total area $A=72(4046.8564224)$ m$^2$. For a hypothetical restoration zone, use meter-coordinate vertices $(0,0),(400,0),(500,300),(0,300)$ in that order.", "model": "The reported reserve area is real. These vertices are invented and are not an actual habitat boundary or GIS survey.", "sources": ["reserve"], "work": "Use the boundary area formula on each straight edge. Explain how it becomes the shoelace formula.", "questions": [{"prompt": "Find polygon area.", "expected": "135000", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Compute half the sum of x_i y_(i+1)−y_i x_(i+1).", "Alternatively the two parallel sides have lengths 400 and 500, separated by 300."], "id": "w09-p2-a", "label": "a"}, {"prompt": "Express model zone area as a percentage of the reported reserve area.", "expected": "100*135000/(72*4046.8564224)", "units": "%", "kind": "number", "tolerance": 1e-05, "hints": ["Use zone area divided by reserve area.", "Multiply the ratio by 100."], "id": "w09-p2-b", "label": "b"}, {"prompt": "Find $\\frac12\\oint(x\\,dy-y\\,dx)$ when traversing this polygon clockwise.", "expected": "-135000", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["The formula gives signed area.", "Reversing a line integral reverses its sign."], "id": "w09-p2-c", "label": "c"}], "solution": ["For a straight edge from $(x_i,y_i)$ to $(x_{i+1},y_{i+1})$, the integral of $x\\,dy-y\\,dx$ is $x_i y_{i+1}-y_i x_{i+1}$.", "The four contributions are $0,120000,150000,0$. Their half-sum is $135000$ m$^2$.", "The percentage is $100(135000)/[72(4046.8564224)]$, about 46.33 percent. Clockwise traversal gives −135000, while geometric area remains positive."], "reflection": "Why should raw latitude and longitude degrees not be inserted as if they were equal-length meter coordinates?", "extension": false, "diagram": "polygon", "discussionSolution": "Latitude and longitude are angular coordinates. Their length scales differ and vary with latitude; planar meter-area calculations require a projection or a stated local conversion.", "id": "w09-p2"}, {"title": "An equal-area model with an excluded island", "context": "Use the Week 4 equal-area ellipse with total area $A=72(4046.8564224)$ m$^2$, semiaxes $a=\\sqrt{2A/\\pi}$ and $b=\\sqrt{A/(2\\pi)}$. Remove an invented centered circular island of radius 50 m.", "model": "The ellipse and island are models; only the 72-acre total is source-derived. The radius-50 disk fits strictly inside the ellipse.", "sources": ["reserve"], "work": "Draw both components of the positive boundary. Parametrize the ellipse and circle and explain the sign of the inner contribution.", "questions": [{"prompt": "Which orientations are positive for the remaining region?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Keep the remaining region on your left.", "The island is outside the integration domain."], "options": ["Both counterclockwise.", "Outer counterclockwise, inner clockwise.", "Outer clockwise, inner counterclockwise."], "id": "w09-p3-a", "label": "a"}, {"prompt": "Find area excluding the island.", "expected": "72*4046.8564224-2500*pi", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Subtract π(50)² from the ellipse area.", "The inner boundary contributes negative signed area."], "id": "w09-p3-b", "label": "b"}, {"prompt": "Find circulation of $(-y,x)$ around the full positive boundary, treating its coefficient as 1 s⁻¹.", "expected": "2*(72*4046.8564224-2500*pi)", "units": "m²/s", "kind": "number", "tolerance": 1e-05, "hints": ["The scalar curl is 2.", "Multiply by the area of the region actually included."], "id": "w09-p3-c", "label": "c"}], "solution": ["Positive orientation is counterclockwise around the ellipse and clockwise around the island. One inner parametrization is $(50\\cos t,-50\\sin t)$.", "The area formula gives outer contribution A and inner contribution $-2500\\pi$, leaving $A-2500\\pi$.", "For $P=-y$, $Q=x$, $Q_x-P_y=2$. Thus circulation is $2(A-2500\\pi)$. The field is smooth across the hole, but the hole’s area is still excluded from D."], "reflection": "What erroneous result would arise if both boundaries were traversed counterclockwise?", "extension": false, "discussionSolution": "The inner disk would add rather than subtract: the area formula would give $A+2500\\pi$ instead of $A-2500\\pi$. The incorrectly oriented curves would not be the positive boundary of the punctured region.", "id": "w09-p3"}, {"title": "A vortex with an excluded center", "context": "Use the idealized field $\\mathbf F=\\kappa(-y,x)/(x^2+y^2)$, with $\\kappa=0.001$ m$^2$/s, on the punctured plane. Let C be a radius-1.5 m circle traversed counterclockwise.", "model": "The geometry uses a rover-derived length scale. This singular vortex is not an observed intake flow, and it is not a model valid at its center.", "sources": ["rover", "pump"], "work": "Compute the circle integral directly. Calculate scalar curl away from the origin and identify the failed Green’s theorem hypothesis.", "questions": [{"prompt": "Find scalar curl away from the center.", "expected": "0", "units": "s⁻¹", "kind": "number", "tolerance": 1e-05, "hints": ["Use the quotient rule for each component.", "The two cross-partials agree away from zero."], "id": "w09-p4-a", "label": "a"}, {"prompt": "Find circulation around C.", "expected": "0.002*pi", "units": "m²/s", "kind": "number", "tolerance": 1e-05, "hints": ["Field magnitude is κ/R and tangent speed is R.", "Their product is κ over 0≤t≤2π."], "id": "w09-p4-b", "label": "b"}, {"prompt": "Why can Green’s theorem not be used on the full disk to conclude zero circulation?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Check whether the field is C¹ throughout the disk.", "Remove a small inner disk before applying the theorem."], "options": ["The circle is too large.", "The field is undefined at the origin inside the disk.", "Counterclockwise is a negative orientation."], "id": "w09-p4-c", "label": "c"}], "solution": ["For $(x,y)\\ne(0,0)$, both cross-partials equal $\\kappa(y^2-x^2)/(x^2+y^2)^2$, so scalar curl is zero.", "On $c(t)=(R\\cos t,R\\sin t)$, $\\mathbf F(c)=(\\kappa/R)(-\\sin t,\\cos t)$ and $\\mathbf F\\cdot c\\prime=\\kappa$. The integral is $2\\pi\\kappa=0.002\\pi$.", "The field is not defined at the center. On an annulus, Green correctly gives outer circulation minus inner counterclockwise circulation equal to zero."], "reflection": "How can a local derivative be zero everywhere in a domain but a loop integral still be nonzero?", "extension": false, "discussionSolution": "Zero scalar curl is a local statement on the punctured domain. The circulation also detects whether the loop encloses the missing singularity; the full-disk hypotheses are not satisfied.", "id": "w09-p4"}, {"title": "A conservation cell and an optimal loop", "context": "In an equal-area planar cell of area $A=72(4046.8564224)$ m$^2$, use $\\mathbf J=(0.002x,0.001y)$ m/s. Separately, in dimensionless coordinates, consider $P=v^3$, $Q=3u-u^3$.", "model": "The cell area is reserve-derived. Both vector fields are synthetic. The second is a mathematical optimization proxy, not a measured environmental benefit.", "sources": ["reserve"], "work": "For J apply flux-form Green. For the second field, use circulation-form Green and decide what region makes the integral largest.", "questions": [{"prompt": "Find divergence of J.", "expected": "0.003", "units": "s⁻¹", "kind": "number", "tolerance": 1e-05, "hints": ["Differentiate each component in its own coordinate.", "Add 0.002 and 0.001."], "id": "w09-p5-a", "label": "a"}, {"prompt": "Find net outward line flux of J.", "expected": "0.003*72*4046.8564224", "units": "m²/s", "kind": "number", "tolerance": 1e-05, "hints": ["This is a two-dimensional flux, per unit vertical depth.", "Multiply constant divergence by area."], "id": "w09-p5-b", "label": "b"}, {"prompt": "Find the maximum possible circulation for the second field among positive simple closed loops.", "expected": "3*pi/2", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Q_u−P_v=3(1−u²−v²).", "Include positive values inside the unit disk and exclude negative values outside."], "id": "w09-p5-c", "label": "c"}], "solution": ["$\\nabla\\cdot\\mathbf J=0.003$ s$^{-1}$, so net outward line flux is $0.003A$ m$^2$/s. A 1-m-thick layer would have that numerical volume rate in m$^3$/s.", "For the second field, Green’s integrand is $h=3(1-u^2-v^2)$. It is positive inside the unit disk and negative outside.", "Any missing interior area loses a positive contribution, and any extra exterior area adds a negative one. Thus the unit circle maximizes circulation, giving $2\\pi\\int_0^1 3(1-r^2)rdr=3\\pi/2$."], "reflection": "Explain why adding a larger region is not always beneficial when the integrand can be negative.", "extension": true, "discussionSolution": "An extra region can contribute a negative integral. For this proxy, adding points outside the unit circle decreases circulation, while excluding points strictly inside loses a positive contribution.", "id": "w09-p5"}]}, {"week": 10, "title": "Stokes’ theorem and conservative fields", "subtitle": "Curl Power", "skills": ["Compute curl component by component", "Match surface and boundary orientations", "Exchange surfaces with the same boundary", "Construct potentials and check domains", "Decide whether a field can be a curl"], "formulas": ["$\\iint_S(\\nabla\\times\\mathbf F)\\cdot\\mathbf n\\,dS=\\oint_{\\partial S}\\mathbf F\\cdot d\\mathbf r$", "$\\nabla\\times\\nabla f=0,\\quad\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$"], "sources": ["rover"], "problems": [{"title": "A dome and a flat disk give the same circulation", "context": "Let S be an upper hemispherical housing of radius a=1.5 m, oriented outward, and let $\\mathbf F=(-y,x,xyz)$ in consistent modeled units.", "model": "The housing and field are hypothetical. Radius is chosen from the published rover-height scale.", "sources": ["rover"], "work": "Find the oriented equator, calculate its line integral, then compute curl flux through the hemisphere and a flat disk.", "questions": [{"prompt": "Enter curl F.", "expected": ["x*z", "-y*z", "2"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Use (F3_y−F2_z,F1_z−F3_x,F2_x−F1_y).", "The third component is 1−(−1)."], "id": "w10-p1-a", "label": "a"}, {"prompt": "Find counterclockwise circulation around the equator.", "expected": "4.5*pi", "units": "modeled circulation units", "kind": "number", "tolerance": 1e-05, "hints": ["At z=0 the field is (−y,x,0).", "The circle dot product is a²."], "id": "w10-p1-b", "label": "b"}, {"prompt": "Find outward curl flux through the hemisphere.", "expected": "4.5*pi", "units": "same circulation units", "kind": "number", "tolerance": 1e-05, "hints": ["Use Stokes with the upward equatorial disk.", "The disk dot product is the constant 2."], "id": "w10-p1-c", "label": "c"}], "solution": ["$\\nabla\\times\\mathbf F=(xz,-yz,2)$. The outward hemisphere induces counterclockwise traversal viewed from above.", "On the equator $c(t)=(a\\cos t,a\\sin t,0)$, the dot product is $a^2$. Thus circulation is $2\\pi a^2=4.5\\pi$.", "On S the unit normal is $(x,y,z)/a$. The x²z and −y²z terms cancel by symmetry; the remaining flux is $(2/a)\\iint_S z\\,dS=2\\pi a^2$. The upward flat disk gives $2\\operatorname{Area}(D)=4.5\\pi$ immediately."], "reflection": "State why matching the geometric boundary without matching its orientation would be insufficient.", "extension": false, "diagram": "dome", "discussionSolution": "Reversing a compatible boundary negates circulation. Stokes requires the boundary orientation induced by the chosen surface normal; matching only the un-oriented curve is insufficient.", "id": "w10-p1"}, {"title": "A tilted inspection loop", "context": "Let C be the intersection of $x^2+y^2=0.25$ and $z=1.5-y$, counterclockwise when viewed from above. Let $\\mathbf F=(-y^2,x,z^2)$ in consistent modeled units.", "model": "The loop is an invented inspection path; 1.5 m is the rover-height scale, not a measured path height.", "sources": ["rover"], "work": "Parametrize C and select a planar spanning surface. Compute its upward vector area and apply Stokes.", "questions": [{"prompt": "Enter a counterclockwise parametrization x(t),y(t),z(t), for 0≤t≤2π.", "expected": ["0.5*cos(t)", "0.5*sin(t)", "1.5-0.5*sin(t)"], "units": "m", "kind": "vector", "tolerance": 1e-05, "hints": ["Use a radius-0.5 circle in the xy projection.", "Set z=1.5−y."], "id": "w10-p2-a", "label": "a"}, {"prompt": "Enter curl F.", "expected": ["0", "0", "1+2*y"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["The first two curl components vanish.", "Differentiate x in x and −y² in y."], "id": "w10-p2-b", "label": "b"}, {"prompt": "Find circulation around C.", "expected": "pi/4", "units": "modeled circulation units", "kind": "number", "tolerance": 1e-05, "hints": ["The graph vector area is (0,1,1)dA.", "The odd 2y term integrates to zero on the radius-0.5 disk."], "id": "w10-p2-c", "label": "c"}], "solution": ["$c(t)=(0.5\\cos t,0.5\\sin t,1.5-0.5\\sin t)$ has the requested orientation.", "Take the plane patch $z=1.5-y$ over the radius-0.5 disk. Its upward vector area is $(0,1,1)dA$, and $\\nabla\\times\\mathbf F=(0,0,1+2y)$.", "Stokes gives $\\iint_D(1+2y)dA=\\operatorname{Area}(D)=\\pi/4$. The odd y term cancels. Do not normalize (0,1,1) without also supplying the surface-area factor."], "reflection": "Why is the projected disk area appropriate here even though the spanning surface is tilted?", "extension": false, "discussionSolution": "The non-unit graph normal (0,1,1) already combines the unit normal and tilted surface-area factor. After the dot product, integration is over the projected disk with dA.", "id": "w10-p2"}, {"title": "A spherical cap reduced to its rim", "context": "Let S be the part of $x^2+y^2+z^2=2.25$ inside $x^2+y^2\\le0.25$ and above z=0, oriented outward. Use $\\mathbf F=(xz,yz,xy)$.", "model": "This cap is an invented housing patch with rover-derived scale. All field coefficients are teaching assumptions.", "sources": ["rover"], "work": "Identify the boundary height and its orientation. Use a line integral instead of computing a surface-area factor.", "questions": [{"prompt": "Find boundary height z.", "expected": "sqrt(2)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["At the rim x²+y²=0.25.", "Subtract it from sphere radius squared 2.25."], "id": "w10-p3-a", "label": "a"}, {"prompt": "Find F(c(t))·c′(t) for the standard counterclockwise rim parametrization.", "expected": "0", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Use c(t)=(0.5cos t,0.5sin t,sqrt(2)).", "The xz and yz terms cancel; dz=0."], "id": "w10-p3-b", "label": "b"}, {"prompt": "Find outward curl flux through S.", "expected": "0", "units": "modeled circulation units", "kind": "number", "tolerance": 1e-05, "hints": ["Apply Stokes.", "The boundary integrand vanishes pointwise."], "id": "w10-p3-c", "label": "c"}], "solution": ["The rim satisfies $z=\\sqrt{2.25-0.25}=\\sqrt2$. Outward on this upper cap induces counterclockwise orientation from above.", "$c(t)=(0.5\\cos t,0.5\\sin t,\\sqrt2)$ and $c\\prime=(-0.5\\sin t,0.5\\cos t,0)$.", "The dot product is $-(\\sqrt2/4)\\cos t\\sin t+(\\sqrt2/4)\\sin t\\cos t=0$. Thus Stokes gives zero curl flux."], "reflection": "Does zero total curl flux require curl to vanish at every point on the cap?", "extension": false, "discussionSolution": "No. Nonzero local flux contributions can cancel. In this problem the boundary dot product vanishes pointwise, which is sufficient for zero total curl flux but does not force curl itself to vanish.", "id": "w10-p3"}, {"title": "A helical route with a potential shortcut", "context": "Use $\\mathbf F=(yz,xz,xy+2z)$ and compare $\\mathbf G=(y,x,y)$. A hypothetical helix is \\[c(t)=(0.5\\cos t,0.5\\sin t,1.5t/(2\\pi)),\\qquad0\\le t\\le2\\pi.\\]", "model": "The helix and fields are invented around a rover-scale instrument. These expressions use consistent nondimensional coefficients rather than measured forces.", "sources": ["rover"], "work": "Compute both curls. Construct a potential for the conservative field and evaluate only the endpoints. Find a closed curve detecting nonzero curl for the other field.", "questions": [{"prompt": "Enter a potential for F.", "expected": "x*y*z+z^2", "units": "", "kind": "potential", "tolerance": 1e-05, "hints": ["Integrate yz with respect to x.", "Matching the third component requires an additional z²."], "id": "w10-p4-a", "label": "a"}, {"prompt": "Find F integral along the helix.", "expected": "2.25", "units": "modeled work units", "kind": "number", "tolerance": 1e-05, "hints": ["The endpoints have y=0 and heights 0 and 1.5.", "Their potential difference is 1.5²."], "id": "w10-p4-b", "label": "b"}, {"prompt": "Enter curl G.", "expected": ["1", "0", "0"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["G3_y=1 and G2_z=0.", "The third component is 1−1."], "id": "w10-p4-c", "label": "c"}], "solution": ["F has zero curl on all of $\\mathbb R^3$ and $f=xyz+z^2+C$ is a potential. G has curl $(1,0,0)$ and is not conservative.", "The helix endpoints are $(0.5,0,0)$ and $(0.5,0,1.5)$, so work is $2.25$. The spatial path is not closed even though its xy projection is.", "A radius-0.5 circle in the yz-plane, $c(t)=(0,0.5\\cos t,0.5\\sin t)$, has G circulation $\\pi/4$, equal to curl flux through its +x-oriented disk."], "reflection": "Explain why the punctured-plane vortex from Week 9 is not a counterexample to the simply connected-domain theorem.", "extension": false, "discussionSolution": "The helix is open in space despite its closed projection. The Week 9 vortex excludes an axis when extended to three dimensions, so its domain is not simply connected and the zero-curl sufficiency hypothesis fails.", "id": "w10-p4"}, {"title": "Which fields can be curls?", "context": "On all of $\\mathbb R^3$, compare $\\mathbf A=(x,y,z)$ and $\\mathbf K=(y,z,x)$ as candidate modeled transport fields.", "model": "These fields are analytical test cases; they do not describe measured MBARI transport.", "sources": ["rover"], "work": "Expand divergence of curl and use equality of mixed partials. Construct a vector potential for K with first component zero.", "questions": [{"prompt": "Find divergence of A.", "expected": "3", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Differentiate each coordinate in its own direction.", "A curl must have divergence zero."], "id": "w10-p5-a", "label": "a"}, {"prompt": "Enter a vector potential F1,F2,F3 whose curl is K, choosing F1=0.", "expected": ["0", "x^2/2", "y^2/2-x*z"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["The second curl equation requires −F3_x=z.", "The third requires F2_x=x; then match the first."], "id": "w10-p5-b", "label": "b", "semantic": "curl", "curlTarget": ["y", "z", "x"], "firstComponentZero": true}, {"prompt": "Find outward flux of K through any closed orientable piecewise smooth surface.", "expected": "0", "units": "modeled flux units", "kind": "number", "tolerance": 1e-05, "hints": ["K is a globally defined curl.", "Apply Stokes patch by patch; shared boundary integrals cancel."], "id": "w10-p5-c", "label": "c"}], "solution": ["For C² fields, the six mixed derivatives in $\\nabla\\cdot(\\nabla\\times\\mathbf F)$ cancel in pairs. A has divergence 3, so it cannot be a curl.", "$\\mathbf F=(0,x^2/2,y^2/2-xz)$ has curl $(y,z,x)=\\mathbf K$. Verify each component directly.", "On a closed surface, patchwise Stokes produces seam integrals twice with opposite directions. Their cancellation gives zero total K flux. The construction relies on a potential defined on a neighborhood of the whole surface."], "reflection": "Why can a singular inverse-square field have nonzero flux through a closed sphere without contradicting this result?", "extension": true, "discussionSolution": "The singular inverse-square field is undefined at the origin. It is not a globally smooth curl on a neighborhood covering a spanning interior, so it does not satisfy the hypothesis used for zero closed-surface flux.", "id": "w10-p5"}]}]};
